COLLDATA("silsila","ur",[[2112,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ ایک آدمی خیبر سے نکلا، دو آدمی اس کے پیچھے چل پڑے اور ایک ان دونوں کے پیچھے۔ (آخری آدمی) ان دو سے کہتا رہا: لوٹ آؤ حتی کہ ان کو پالیا اور واپس لوٹا دیا، پھر پہلے کو جا ملا اور اسے کہا: یہ دو شیطان تھے، میں ان کو پھسلاتا رہا، حتی کہ ان کو واپس کر دیا۔ جب تو رسول اللہ صلی اللہ علیہ وسلم کے پہنچے تو آپ کو میرا سلام دینا اور بتلانا کہ میں ادھر زکوۃ جمع کر رہا ہوں، اگر وہ آپ کے لیے مناسب ہے تو ہم بھیج دیں گے۔ جب وہ آدمی نبی کریم صلی اللہ علیہ وسلم کے پاس پہنچا تو سارا واقعہ بیان کیا، اس وقت آپ صلی اللہ علیہ وسلم نے خلوت سے منع کر دیا۔","",{"t":"دورانِ سفر تنہائی سے منع کر دیا","k":"أخرجه الحاكم: ۲/۱۰۲، والبيهقي في \"الدلائل\": ۲/۲/۲۲۹/۲، وكذا البزار في \"مسنده\": رقم ۲۰۲۲ - كشف الأستار\n(الصحيحة: ۲۶۵۸)","e":"امام البانی رحمہ اللہ نے کہا: اس حدیث مبارکہ میں خلوت اور تنہائی سے منع کرنے کی ایسی وجہ بیان کی جا رہی ہے، جو ہمارے لیے معقول المعنی نہیں ہے اور اس تفسیر کے خلاف ہے، جو میں امام طبری کے حوالے سے صحیحہ کی حدیث نمبر (۶۲) میں بیان کی۔ (صحیحہ: ۲۶۵۸)"}],[2113,"سیدنا صخر بن عیلہ رضی اللہ عنہ کہتے ہیں کہ جب اسلام کا ظہور ہوا تو بنو سلیم قبیلہ کے کچھ لوگ اپنی زمینوں کو چھوڑ کر بھاگ گئے، میں نے ان پر قبضہ کر لیا اور وہ مسلمان ہو (کر واپس آ) گئے اور اس کے بارے میں نبی صلی اللہ علیہ وسلم تک جھگڑا لے گئے۔ آپ صلی اللہ علیہ وسلم نے انھیں زمینیں واپس دلا دیں اور فرمایا: ”جب کوئی آدمی مسلمان ہو جاتا ہے تو وہ اپنی زمین اور مال کا زیادہ حقدار ہوتا ہے۔“","",{"t":"اسلام قبول کرنے والا اپنی جائداد کا زیادہ مستحق ہے","k":"أخرجه أحمد: ۴/۳۱۰\n(الصحيحة: ۱۲۳۰)","e":"معلوم ہوا کہ اس قسم کی جائداد کا حقدار اس کا اصل مالک ہے، ذہن نشین رہنا چاہیے کہ کفر کی وجہ سے کافر کی ملکیت میں کوئی فرق نہیں آتا، غنیمت وغیرہ کے مسائل اس سے مختلف ہیں۔"}],[2114,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ”جب تو اپنے گھر سے نکلنے لگے تو دو رکعت نماز ادا کر لیا کر، کیونکہ یہ تجھے برے نکلنے سے روک لیں گی اور جب تو اپنے گھر میں داخل ہونے لگے تو دو رکعت نماز پڑھ لیا کر، یہ تجھے برے داخلے سے روک لیں گی۔“","",{"t":"گھر سے نکلتے اور داخل ہوتے وقت دو رکعت نماز پڑھنا","k":"رواه المخلص في \"حديثه\" كما في \"المنتقي منه\": ۱۲/۶۹/۱، والبزار في \"المسند\": ۸۱، والديلمي في \"مسنده\": ۱/۱/۱۰۸\n(الصحيحة: ۱۳۲۳)","e":"ان چار رکعات کی وجہ سے آدمی گھر کے اندر اور گھر سے باہر پائی جانے والی ہر شر سے محفوظ رہتا ہے۔"}],[2115,"سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب فارس (ایران) اور روم کے خزانے تمھارے لیے فتح کر لیے جائیں گے تو تم اس وقت کس قسم کے لوگ ہو گے؟“ سیدنا عبدالرحمن بن عوف رضی اللہ عنہ نے کہا: ہم وہی بات کہیں گے، جس کا اللہ تعالیٰ نے ہمیں حکم دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کوئی اور بات بھی ہے؟ پہلے تو تم بڑھ چڑھ کر حصہ لو گے، پھر ایک دوسرے سے حسد کرو گے، پھر باہم قطع تعلق ہو کر ایک دوسرے سے دشمنی کرو گے، پھر ایک دوسرے سے منافرت رکھو گے اور اس قسم کی (قبیح عادتیں) اپناؤ گے اور پھر مہاجروں کے گھروں پر ہلہ بول دو گے اور ان کو ایک دوسرے سے لڑا دو گے۔“","",{"t":"مال و دولت کی کثرت کا وبال","k":"أخرجه مسلم: ۸/۲۱۲، وابن ماجه: ۲/۴۸۱\n(الصحيحة: ۲۶۶۵)","e":"سیدنا عبدالرحمن بن عوف رضی اللہ عنہ کے جواب کا یہ مطلب ہے کہ وہ پہلے سے بڑھ کر اللہ تعالیٰ کی حمد و ثنا بیان کریں گے، اس کا شکر ادا کریں گے اور اس سے مزید فضل کا سوال کریں گے۔ مال و دولت کی وجہ سے سب سے پہلے مالداروں میں مقابلہ بازی شروع ہوتی ہے، جو حسد کا پہلا درجہ ہے، پھر معاملہ حسد تک جا پہنچتا ہے اور وہ ایک دوسرے سے نعمت کے چھن جانے کی خواہش کرنے لگتے ہیں، جس کا نتیجہ قطع رحمی کی صورت میں نکلتا ہے، جو بغض و عداوت کو جنم دیتی ہے۔ دنیوی آسائشیں، اللہ تعالیٰ کے انعامات میں سے ہیں، وہ مال و دولت کی صورت میں ہوں یا عہدہ و منصب کی صورت میں۔ بہر حال دنیا نے اکثر لوگوں کو اپنے اثرات کا پابند کر دیا اور ان کو اسلامی مزاجوں کا نہیں رہنے دیا۔ وہ آسائشوں اور سہولتوں کے اس قدر غلام بن جاتے ہیں کہ فقر و فاقہ میں مبتلا لوگوں کے مصائب کو پہچاننا ان کے لیے دشوار ہو جاتا ہے۔ بہر حال کوئی دولتمند ان حقائق سے اتفاق نہیں کرے گا، کیونکہ وہ اپنے دماغ کے مطابق اپنے آپ کو انسانِ کامل سمجھتا ہے۔"}],[2116,"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تین آدمی سفر پر ہوں تو ان میں سے ایک دوسروں کو امامت کروائے اور اس کا حقدار وہی ہوگا جسے قرآن مجید زیادہ یاد ہوگا۔“","",{"t":"تین مسافر با جماعت نماز ادا کریں","k":"أخرجه مسلم: ۲/۳۳، والدارمي: ۲۸۶، والنسائي: ۱/۱۳۵، وابن خزيمة: ۳/۴/۱۵۰۸، وابن حبان: ۳/۲۸۷/۲۱۲۹، والبيهقي: ۳/۱۱۹، والطيالسي: ۳۸۶/۲۱۵۲، ومن طريقه: البيهقي أيضا، وابن أبي شيبة: ۱/۳۴۳، وأحمد: ۳/۲۴، ۳۴، ۳۶، ۴۸، ۵۱، ۸۴\n(الصحيحة: ۳۹۷۹)","e":"باجماعت نماز ادا کرنے کی بہت زیادہ تاکید کی گئی ہے، ہمارے ہاں اکثر لوگ، جو نماز کے پابند ہوتے ہیں، وہ دوران سفر سرے سے نماز ادا کرنے سے ہی غافل ہو جاتے ہیں، جماعت کا اہتمام کرنا تو دور کی بات ہے۔ (انظر: ۸/۱۴۱۷)"}],[2117,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم حجر مقام (منازل ثمود) کے پاس سے گزرے تو فرمایا: ”جن مکانات میں گزشتہ اقوام کو عذاب دیا گیا وہاں روتے ہوئے داخل ہوا کرو، اگر تم نہیں رو سکتے تو وہاں داخل نہ ہوا کرو۔ کہیں ایسا نہ ہو کہ تمھیں بھی اسی عذاب میں مبتلا کر دیا جائے۔“ پھر آپ نے کجاوہ پر بیٹھے بیٹھے اپنی چادر اوپر اوڑھ لی۔","",{"t":"معذب اقوام کی جائے عذاب سے کیسے گزرا جائے؟","k":"اخرجه البخاري: ۱/۱۲۰، ومسلم: ۸/۲۲۱، وأحمد: ۲/۹ و ۵۸ و ۶۶ و ۷۲ و ۷۴ و ۹۱ و ۹۶ و ۱۱۳ و ۱۳۷\n(الصحيحة: ۱۹)","e":"صحیح بخاری کی ایک روایت میں ہے کہ پھر آپ صلی اللہ علیہ وسلم نے جلدی چلنا شروع کر دیا، یہاں تک کہ وادی کو عبور کر گئے اور صحیح مسلم کی روایت میں ہے کہ آپ صلی اللہ علیہ وسلم نے اپنی اونٹنی کو ڈانٹا اور اس کو جلدی چلانا شروع کیا۔"}],[2118,"سیدنا ابو امامہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”جب تم ایسی زمین سے گزرو، جہاں کوئی امت ہلاکت ہوئی ہو، تو تیز چلا کرو۔“","",{"t":"معذب اقوام کی جائے عذاب سے کیسے گزرا جائے؟","k":"أخرجه أبو الشيخ في \"الطبقات\": ق ۵۲/۱، وعنه أبو نعيم في \"أخبار أصبهان\": ۲/۱۳۹، والطبراني في \"الكبير\": ۸/۳۳۳/۸۰۶۸، ۸۰۶۹\n(الصحيحة: ۳۹۴۱)","e":"امام البانی رحمہ اللہ کہتے ہیں: صدیق حسن نے ”نزل الابرار ص ۲۹۳“ میں اس حدیث پر یہ باب باندھا ہے: ”ظالموں کی قبروں اور ان کی ہلاکت گاہوں کے پاس سے گزرتے وقت رونا اور ڈرنا اور اللہ تعالیٰ کے سامنے اپنی فقیری کا اظہار کرنا اور ایسا کرنے سے غافل رہنے سے بچنا۔ میں اللہ تعالیٰ سے سوال کرتا ہوں کہ وہ ہمیں فقاہت فی الدین عطا فرمائے اور نیک عمل کرنے کی توفیق سے نوازے، بیشک وہ سننے والا اور دعائیں قبول کرنے والا ہے۔ (صحیحہ: ۱۹) لہذا قومِ عاد، قوم ثمود اور اصحاب الفیل جیسی قوموں کی ہلاکت گاہوں سے گزرتے وقت وہی انداز اختیار کرنا چاہئے، جس کا اس حدیث میں بیان ہے۔"}],[2119,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”جب گھمسان کی جنگیں ہوں گی تو اللہ تعالیٰ دمشق سے مخلص لوگوں کو بھیجے گا، وہ تمام عربوں میں عمدہ ترین شہسوار اور آلات حرب کی مہارتِ تامہ رکھنے والے ہوں گے۔ اللہ ان کے ذریعے اپنے دین کو محکم کرے گا۔“","",{"t":"اہل دمشق دین کے معاون","k":"أخرجه ابن ماجه: ۴۰۹۰، والحاكم: ۴/۵۴۸، وابن عساكر في \"تاريخ دمشق\": ۱/۲۵۸\n(الصحيحة: ۲۷۷۷)","e":"عام احادیث میں دمشق اور اہل دمشق کی فضیلت بیان کی گئی ہے، پرفتن دور میں اس کی اہمیت قلعہ کی ہے، ابن عساکر کے بیان کے مطابق دس ہزار صحابہ دمشق میں داخل ہوئے اور نبی کریم صلی اللہ علیہ وسلم قبل از بعثت اور بعد از بعثت اسرا و معراج اور غزوہ تبوک کے موقع پر اس میں داخل ہوئے تھے۔ اس حدیث کی تفصیل ”المناقب والمثالب میں شام اور اہل شام کی فضیلت“ کے عنوان میں موجود ہے۔"}],[2120,"عبدالرحمن بن شماسہ سے روایت ہے کہ فقیم لخمی نے سیدنا عقبہ بن عامر رضی اللہ عنہ سے کہا: تم ان دو نشانوں کے درمیان آتے جاتے رہتے ہو، حالانکہ تم عمر رسیدہ ہو اور یہ عمل تمہارے لیے باعث مشقت ہو گا۔ سیدنا عقبہ نے کہا: اگر میں نے رسول اللہ صلی اللہ علیہ وسلم سے ایک حدیث نہ سنی ہوتی تو اس مشقت میں نہ پڑتا۔ حارث نے کہا: میں نے ابن شماسہ سے کہا: وہ کون سی حدیث ہے؟ انھوں نے کہا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے تیراندازی سیکھی اور پھر ترک کر دی، وہ ہم میں سے نہیں ہے۔“ یا آپ نے فرمایا کہ ”اس نے نافرمانی کی۔“","",{"t":"تیراندازی کی ترغیب","k":"أخرجه مسلم: ۶/۵۲، وأبو عوانة: ۵/۱۰۲ - ۱۰۳، والبيهقي في \"السنن\": ۱۰/۱۳، والروياني في \"مسنده\": ۱/۱۶۳/۱۹۵، والطبراني في \"المعجم الكبير\": ۱۷/۳۱۸/۸۸۲\n(الصحيحة: ۳۴۴۸)"}],[2121,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم صحابہ کی ایک جماعت، جو تیر اندازی کر رہی تھی، کے پاس سے گزرے اور فرمایا: ”اے اولاد اسماعیل! تم تیر اندازی کرو، اس لیے کہ تمھارے باپ بھی تیرانداز تھے۔“","",{"t":"تیراندازی کی ترغیب","k":"رواه أحمد بن محمد الزعفراني في \"فوائد أبي شعيب\": ۸۲/۱، وأخرجه ابن حبان: ۱۶۴۶، والحاكم: ۲/۹۴ بلفظ: ((...... ارموا وانا معكم - ))\n(الصحيحة: ۱۴۳۹)"}],[2122,"مصعب بن سعد بن ابو وقاص رضی اللہ عنہ اپنے باپ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم تیراندازی کیا کرو، کیونکہ یہ بہترین کھیل و تفریح ہے۔“","",{"t":"تیراندازی کی ترغیب","k":"رواه البزار في \"مسنده\": ۲/۲۷۹/۱۷۰۱ - الكشف، والطبراني في \"الأوسط\": ۳/۳۹/۲۰۷۰ ط، وأبو حفص المؤدب في \"المنتقى من حديث ابن مخلد وغيره\": ۲۲۵/۲، والخطيب في \"الموضح\": ۲/۳۰\n(الصحيحة: ۶۲۸)","e":"کئی احادیث میں تیراندازی کرنے کی تعلیم و ترغیب دی گئی ہے، بلکہ آپ صلی اللہ علیہ وسلم کی حدیث ہے کہ اللہ تعالیٰ کے فرمان ﴿وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ﴾ (سورہ انفال: ۶۰) میں لفظ ”قوة“ سے مراد تیر اندازی ہے۔ آپ صلی اللہ علیہ وسلم کے دور میں تیر اندازی بہت بڑا جنگی ہتھیار اور نہایت اہم فن تھا، لیکن اب سائنسی ترقی کی وجہ سے گنوں، میزائلوں، ٹینکوں، بموں، جنگی جہازوں، آبدوزوں کی تیاری اور حسب استطاعت ان کی تعلیم حاصل کرنا اور مشق کرنا ضروری ہے۔ بہر حال تیر اندازی اور تلوار زنی وغیرہ جیسے فن ہمارا اصل ورثہ ہیں، اس لیے ان کو برقرار رکھنا بھی ضروری ہے، کیونکہ اس مادی ترقی کے زوال کے بعد جنگ و جدل کا پرانا طریقہ پھر سے شروع ہو جائے گا۔"}],[2123,"سیدنا عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر جہاد کرنے کا ارادہ ہے تو ایسا گھوڑا خرید کر رکھو جس کا رنگ کالا ہو، پیشانی اور ٹانگوں میں بیڑی کی جگہ سفید ہو اور اس کی ایک یا دونوں ٹانگوں میں سفید حلقہ نہ ہو۔ (اگر ایسا گھوڑا ہوا تو) تو مال غنیمت پاؤ گے اور سالم رہو گے۔“","",{"t":"بہترین گھوڑوں کی صفات","k":"أخرجه الحاكم: ۲/۹۲، والطبراني في \"المعجم الكبير\": ۱۷/۲۹۳/۸۰۹\n(الصحيحة: ۳۴۴۹)","e":"اگرچہ قرآن وحدیث میں مطلق طور پر گھوڑوں کو خیر و برکت کی علامت قرار دیا گیا ہے، بہرحال بعض گھوڑوں کو ان کی عمدہ صفات کی بنا پر بعض پر ترجیح دی گئی ہے۔"}],[2124,"یحی بن سعید (مرسلاً) روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو اس حال میں دیکھا گیا کہ آپ اپنے گھوڑے کا چہرہ اپنی چادر سے پونچھ رہے تھے، جب آپ صلی اللہ علیہ وسلم سے اس کے بارے میں دریافت کیا گیا تو فرمایا: ”گزشتہ رات مجھے گھوڑوں کے بارے میں ڈانٹا گیا۔","",{"t":"جہاد کی خاطر گھوڑوں کی نگہداشت کرنا","k":"أخرجه ابن أبي شيبة في \"المصنف\": ۸/۲۰۵/۴۱۷۰، وأحمد: ۲/۱۰۸، والترمذي: ۶/۱۴۸/۱۸۸۰، والطحاوي في \"شرح المعاني\": ۲/۳۵۸، والبيهقي في \"السنن\": ۷/۲۸۳، والطيالسي في \"مسنده\": ۲۵۸/۱۰۹۴\n(الصحيحة: ۳۱۸۷)"}],[2125,"سیدنا سوادہ بن ربیع رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم نے میرے لیے کچھ اونٹوں کا حکم دیا اور مجھے فرمایا: ”اپنے بیٹوں کو حکم دینا کہ اپنے ناخن کاٹ دیں تا کہ اونٹنیوں اور دوسرے مویشیوں کے تھنوں کو تکلیف نہ ہو، اور انھیں یہ بھی کہنا کہ وہ دودھ دوہیں اور ان کے بچوں کے لیے بھی چھوڑیں، کہیں ایسا نہ ہو کہ قحط سالی کی وجہ سے وہ لاغر و کمزور ہو جائیں۔“ پھر آپ صلی اللہ علیہ وسلم نے پوچھا: ”تیرے پاس کوئی مال ہے؟“ میں نے کہا: جی ہاں، میرے پاس مال، گھوڑے اور غلام ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”گھوڑوں کو پالنے کا اہتمام کیے رکھ، ان کو سرحدی حفاظت کے لیے تیار رکھ۔ گھوڑے کی پیشانی کے ساتھ خیر وابستہ ہے۔“","",{"t":"جہاد کی خاطر گھوڑوں کی نگہداشت کرنا","k":"أخرجه البخاري في \"التاريخ\": ۲/۲/۱۸۴، ورواه أحمد: ۳/۴۸۴ دون قوله: ((وقل لهم فليحتلبوا ...... - )) ورواه الطبراني والبزار بلفظ: ((الخيل معقود في نواصيها الخير - ))\n(الصحيحة: ۱۹۳۶)","e":"اللہ تعالیٰ نے خاص طور پر گھوڑوں کو پالنے کی تلقین کی ہے، تا کہ دشمن ڈرتے رہیں، کیونکہ قدیم زمانے میں گھوڑے جنگ کے لیے کلیدی حیثیت رکھتے تھے۔ اگر چہ اب سائنسی ترقی کی وجہ سے جنگی آلات میں بہت زیادہ تبدیلی آچکی ہے، اس لیے ان کے بارے میں تعلیم حاصل کرنا اور ان کی مشق کرنا ضروری ہے۔ بہر حال گھوڑوں کے سلسلے کو جاری رکھنا بھی ضروری ہے۔ ایک حدیث میں آپ صلی اللہ علیہ وسلم نے جانوروں کو تکلیف سے بچانے اور ان کے بچوں کے ساتھ حسن سلوک سے پیش آنے کی تلقین فرمائی ہے۔"}],[2126,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ گھوڑوں کی دوڑ کرانے کے لیے ان کی تضمیر کرتے تھے۔","",{"t":"تضمير","k":"أخرجه أبو داود: ۱/۴۰۳، تازية، ورواه ابن ماجه: ۲/۲۰۵ نحوه\n(الصحيحة: ۲۱۳۳)","e":"جدید سائنسی دور سے پہلے جنگ کے لیے گھوڑے مرکزی حیثیت رکھتے تھے، اس لیے ان کی تربیت پر خوب توجہ دی جاتی تھی۔ تضمیر میں گھوڑے کو خوب چارہ کھلایا جاتا ہے، حتی کہ وہ موٹا اور قوی ہو جاتا ہے، پھر اس کا چارہ کم کر کے اتنی مقدار تک لایا جاتا ہے، جو اس کے بدن کی بقا کے لیے ضروری ہو، اس عرصے میں اسے ایک کمرے میں داخل کیا جاتا ہے اور اس پر جھول وغیرہ ڈال دی جاتی ہے، حتی کہ وہ گرم ہو جاتا اور اسے پسینہ آتا ہے، جب اس کا پسینہ خشک ہوتا ہے تو اس کا گوشت کم ہو جاتا ہے اور اس میں دوڑنے کی طاقت پیدا ہو جاتی ہے۔"}],[2127,"سیدنا سہل بن حنظلیہ رضی اللہ عنہ سے روایت ہے کہ حنین والے دن صحابہ، رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہے تھے، دیر تک چلتے رہے، حتی کہ شام ہو گئی۔ نماز کا وقت آ گیا۔ ایک گھوڑ سوار آیا اور کہا: اے اللہ کے رسول صلی اللہ علیہ وسلم! میں آپ کے آگے آگے چلتا رہا اور فلاں فلاں پہاڑ کو عبور کرتا گیا، حتی کہ صبح سویرے ہوازن قبیلے تک پہنچ گیا، ان کے آباء اپنی بیویوں، اونٹوں اور بھیڑ بکریوں سمیت حنین میں جمع ہیں۔ رسول اللہ صلی اللہ علیہ وسلم مسکرائے اور فرمایا: ”یہ مال تو کل مسلمانوں کی غنیمت بننے والا ہے، ان شاء اللہ تعالیٰ۔“ پھر فرمایا: ”آج رات کون پہرہ دے گا؟“ انس بن ابو مرثد غنوی نے کہا: اے اللہ کے رسول صلی اللہ علیہ وسلم! میں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”سوار ہو جا۔“ وہ اپنے گھوڑے پر سوار ہوا اور رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس گھائی کی طرف چلنا شروع کر دے اور اس کی بلند چوٹی تک پہنچ جا، ہمیں آج رات تیری سمت سے کوئی دھوکا نہیں دیا جانا چاہئے۔“ جب صبح ہوئی تو رسول اللہ صلی اللہ علیہ وسلم جائے نماز کی طرف نکلے، دو رکعت سنتیں پڑھیں اور پوچھا: ”کیا تم نے اپنے گھوڑ سوار کو محسوس کیا؟“ انھوں نے کہا: اے اللہ کے رسول صلی اللہ علیہ وسلم! ہمیں تو محسوس نہیں ہوا۔ پھر اقامت کہی گئی، رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھانا شروع کی اور نماز میں ہی اس گھائی کی طرف متوجہ ہوتے رہے، یہاں تک کہ نماز مکمل کی اور سلام پھیرا۔ پھر فرمایا: ”خوش ہو جاؤ، تمھارا گھوڑ سوار آ گیا ہے۔“ ہم نے گھائی کے درختوں کے بیچ سے دیکھنا شروع کر دیا۔ اچانک وہ پہنچ گیا، رسول اللہ صلی اللہ علیہ وسلم کے سامنے کھڑا ہوا، سلام دیا اور کہا: رسول اللہ صلی اللہ علیہ وسلم کے حکم کے مطابق میں گیا اور وادی کی چوٹی تک پہنچ گیا، جب صبح ہوئی تو میں نے دو گھاٹیوں کو عبور کیا، لیکن کوئی آدمی مجھے نظر نہ آیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: ”کیا تو رات کو اپنی سواری سے اترا ہے؟“ اس نے کہا: نہیں، مگر نماز پڑھنے یا قضائے حاجت کرنے کے لیے۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ”تو نے (اپنے حق میں جنت کو) واجب کر دیا ہے، آج کے بعد اگر عمل نہ بھی کرے تو کوئی حرج نہیں۔“","",{"t":"جہادی سفر میں پہرہ داری اور اس کی فضیلت","k":"أخرجه أبو داود: ۱/۳۹۱، والحاكم: ۲/۸۳-۸۴، والنسائي في \"سننه الكبرى\"\n(الصحيحة: ۳۷۸)","e":"جہادی سفر میں ایک رات کے پہرے کو آئندہ عمل نہ کرنے کے باوجود جنت کے لیے کافی قرار دیا گیا۔"}],[2128,"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کہ نبی صلی اللہ علیہ وسلم نے فرمایا (بسا اوقات وہ اس حدیث کو آپ صلی اللہ علیہ وسلم کی طرف منسوب نہیں کرتے تھے): ”کیا میں تمھیں ایسی رات کے بارے میں بتلاؤں جو شب قدر سے بھی زیادہ فضیلت والی ہے؟ (وہ رات جس میں) آدمی ایسی سرزمین میں پہرہ دے رہا ہو، جہاں خوف و دہشت ہو اور اسے یہ اندیشہ ہو کہ شاید وہ اپنے گھر والوں کی طرف نہ لوٹ سکے۔“","",{"t":"جہادی سفر میں پہرہ داری اور اس کی فضیلت","k":"أخرجه الروياني في \"مسنده\": ق ۲۴۷/۲، والحاكم: ۲/۸۰، والبيهقي: ۹/۱۴۹\n(الصحيحة: ۲۸۱۱)","e":"اس حدیث میں ایک وجہ فضیلت بھی بیان کی گئی ہے کہ پہرہ دار نہ صرف جاگ رہا ہوتا ہے، بلکہ اسے یہ خطرہ بھی لاحق ہوتا ہے کہ شاید وہ اسی رات کسی حملے کی وجہ سے دنیائے فانی سے کوچ کر جائے اور اپنے بیوی بچوں کے پاس نہ پہنچ پائے۔"}],[2129,"قزعہ کہتے ہیں کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ نے مجھے کسی کام کیلیے بھیجنا چاہا اور کہا: ادھر آؤ، تاکہ میں تجھے الوداع کہوں، جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے الوداع کہہ کر اپنے ضرورت کے لیے بھیجا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا تھا: ”میں تیرے دین کو، تیری امانت کو اور تیرے آخری عمل کو اللہ کے سپرد کرتا ہوں۔“","",{"t":"اسلامی آداب بوقت الوداع","k":"رواه أبوداود: ۲۶۰۰، والحاكم: ۲/۹۷، وأحمد: ۳۸ و ۱۳۶، وابن عساکر: ۱۴/۲۹۰/۲ و ۱۵/۴۶۹/۱، والترمذي: ۲/۲۵۵\n(الصحيحة: ۱۴)","e":"ابن حبان اور طبرانی کی روایت میں اس دعا کی یہ وجہ بھی بیان کی گئی ہے کہ جب کوئی چیز اللہ تعالیٰ کے سپرد کی جاتی ہے تو وہ اس کی حفاظت کرتا ہے۔"}],[2130,"سیدنا عبداللہ خطمی رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم کسی لشکر کو الوداع کہنے کا ارادہ کرتے تو فرماتے: ”میں تیرے دین کو، تیری امانت کو اور تیرے آخری عمل کو اللہ کے سپرد کرتا ہوں۔“","",{"t":"اسلامی آداب بوقت الوداع","k":"(أ) رواه أبو داود: ۲۶۰۱، والنسائي في \"عمل اليوم والليلة\": ۵۰۷، وابن السني في \"عمل اليوم والليلة\": ۴۹۸، والحاكم: ۲/۹۷-۹۸، (ب) أخرجه الترمذي: ۲/۲۵۵ - طبع بولاق، وأحمد: ۲/۷، والطبراني في \"الدعاء\": ۸۲۱، وعبد الغني المقدسي في \"الجزء الثالث والستون\": ۴۱/۱ -، (ج) أخرجه ابن حبان في \"صحيحه\": ۲۳۷۶، والطبراني في \"الدعاء\": ۸۲۸، وفي \"المعجم الأوسط\": ۲/۲۸۶/۲/۴۸۰۴ بترقيمي، (د) رواه الترمذي: ۲/۲۵۵ طبع بولاق\n(الصحيحة: ۱۵)"}],[2131,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ جب نبی صلی اللہ علیہ وسلم کسی کو الوداع کہتے تو فرماتے: ”میں تیرے دین کو، تیری امانت کو اور تیرے آخری عمل کو اللہ کے سپرد کرتا ہوں۔“","",{"t":"اسلامی آداب بوقت الوداع","k":"أخرجه أحمد: ۲/۳۵۸\n(الصحيحة: ۱۶)","e":"معلوم ہوا کہ مقیم، مسافر کو الوداع کرتے ہوئے یہ دعا پڑھے: أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ۔ اور مسافر یوں جواب دے: أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ۔"}],[2132,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے اپنے سامنے والے دانتوں کی طرف اشارہ کرتے ہوئے فرمایا: ”ان لوگوں پر اللہ تعالیٰ سخت ناراض ہوا جنھوں نے اپنے نبی کے ساتھ یہ کیا۔ اس آدمی پر بھی اللہ تعالیٰ سخت غضبناک ہوتا ہے جس کو اللہ کا رسول، جو جہاد کر رہا ہو قتل کرتا ہے۔“","",{"t":"رسول کو تکلیف پہنچانے والا اور رسول کا مقتول دونوں عذاب الہی کے مستحق ہیں","k":"أخرجه البخاري: ۵/۳۷، ومسلم: ۵/۱۷۹\n(الصحيحة: ۱۴۶۰)","e":"آپ صلی اللہ علیہ وسلم نے غزوہ احد میں زخمی ہونے کے بعد یہ حدیث بیان کی تھی۔ اس حدیث سے یہ بھی معلوم ہوا کہ انبیا و رسل بھی دنیوی تکالیف و مصائب میں مبتلا ہو سکتے ہیں۔"}],[2133,"سیدنا عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ میں نے شام سے مدینہ کی طرف جمعہ والے دن سفر شروع کیا۔ میں سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس آیا۔ انھوں نے پوچھا: تو نے اپنے پاؤں موزوں میں کب داخل کئے تھے؟ میں نے کہا: جمعہ کے دن۔ انھوں نے کہا: کیا ان کو اتارا بھی ہے؟ میں نے کہا: نہیں۔ انھوں نے کہا: تو نے سنت کی موافقت کی ہے۔","",{"t":"مسافر کو سات ایام تک موزوں پر مسح کرنے کی اجازت","k":"أخرجه الطحاوي في \"شرح المعاني\": ۱/۴۸، والدارقطني في \"السنن\": ص ۷۲، والحاكم: ۱/۱۸۰-۱۸۱، وعنه البيهقي في \"السنن\": ۱/۲۸۰\n(الصحيحة: ۲۶۲۲)","e":"امام البانی رحمہ اللہ رقمطراز ہیں: ایسے لگتا ہے کہ امام بیہقی اور امام نووی وغیرہ نے بھی اس حدیث کو صحیح کہا، کیونکہ انھوں نے اس کو مسح کے لیے ایک اور تین ایام کے تعین پر دلالت کرنے والی احادیث کے تعارض میں ذکر کیا اور ضعیف نہیں کہا۔۔۔۔۔ (موزوں پر مسح کرنے کے بارے میں متعارض قسم کی روایات مروی ہیں، ایک حدیث کے مطابق مقیم ایک دن تک اور مسافر تین دنوں تک مسح کر سکتا ہے، جبکہ اس حدیث سے ثابت ہوتا ہے کہ مسافر کو سات ایام تک مسح کرنے کی رخصت ہے۔) ان دو احادیث میں اس طرح جمع و تطبیق ممکن ہے کہ سات دنوں والی روایت کو ضرورت اور جماعت کی معیت میں رہنے کی وجہ سے موزے نہ اتار سکنے پر محمول کیا جائے، شیخ الاسلام امام ابن تیمیہ کا بھی یہی خیال ہے۔ (صحیحہ: ۲۶۲۲)"}],[2134,"سیدنا برا بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو قریظہ والے دن سیدنا حسان بن ثابت رضی اللہ عنہ کو فرمایا: ”(اشعار کے ذریعے) مشرکوں کی مذمت کرو، بیشک جبریل (علیہ السلام) تمہارے ساتھ ہے۔“","",{"t":"شعروں کے ذریعے دشمن کی مذمت کرنا","k":"أخرجه البخارى: ۵/۵۱ تعليقا، وأحمد: ۴/۲۸۶ و ۳۰۳ موصولا، وكذا الخطيب: ۱۴/۳۱، ثم اخرجه البخاري: ۴/۷۹، ۵/۵۱، ۷/۱۰۹، ومسلم: ۷/۱۶۳\n(الصحيحة: ۸۰۱)"}],[2135,"سیدنا کعب بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے کہا: بیشک اللہ تعالیٰ نے اشعار کے بارے میں جو کچھ نازل کیا، وہ نازل کیا (تو اب شعروں کے بارے میں کیا خیال ہے؟) آپ صلی اللہ علیہ وسلم نے فرمایا: ”بلاشبہ مومن اپنی تلوار اور زبان دونوں سے جہاد کرتا ہے اور اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! جو کچھ تم انھیں زبان سے کہتے ہو (یعنی شعروں کے ذریعے دشمنوں کی مذمت کرتے ہو) وہ ان پر تیروں کے برسنے کی طرح (اثر کرتا ہے)۔“","",{"t":"شعروں کے ذریعے دشمن کی مذمت کرنا","k":"أخرجه أحمد: ۶/۳۸۷\n(الصحيحة: ۱۶۳۱)"}],[2136,"سیدنا کعب بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! (دشمنوں کی مذمت کرتے ہوئے) جو تم شعر کہتے ہو یہ (ان پر) تیر برسانے کی طرح ہیں۔“","",{"t":"شعروں کے ذریعے دشمن کی مذمت کرنا","k":"أخرجه أحمد: ۳/۴۵۶\n(الصحيحة: ۱۹۴۹)","e":"معلوم ہوا کہ جنگ و جدل کے موقع پر مشرکین کی ہجو اور مذمت کر کے اور ان کے عیوب بیان کر کے ان کی توہین کرنی چاہئے۔ سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «جَاهِدُوا الْمُشْرِكِينَ بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ وَأَلْسِنَتِكُمْ -» (ابوداود، نسائی) ..... ”اپنے مالوں، جانوں اور زبانوں کے ساتھ مشرکوں سے جہاد کرو۔“ زبان کے جہاد سے مراد دلائل کے ذریعے ان پر حجت قائم کرنا، ان کو اللہ تعالیٰ کی طرف بلانا اور دورانِ جنگ ان کی ہجو کرنا ہے۔"}],[2137,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے، اچانک ایک نوجوان پہاڑی راستے کو عبور کرتا ہوا آ رہا تھا، جب ہم نے اسے (ایک دفعہ) دیکھا تو پھر ٹکٹکی باندھ کر دیکھتے رہے۔ ہم نے کہا: کاش یہ نوجوان اپنی نوجوانی، مستعدی اور قوت کو اللہ کے راستے میں صرف کرتا۔ رسول اللہ صلی اللہ علیہ وسلم نے ہماری یہ بات سنی اور فرمایا: ”کیا اللہ کا راستہ یہی ہے کہ آدمی شہید ہو جائے؟ (نہیں، بلکہ) جس نے والدین کی خدمت کی وہ بھی اللہ کے راستے میں ہے، جس نے اپنے اہل وعیال کو پالا پوسا وہ بھی اللہ کی راہ میں ہے اور جس نے اپنے آپ کو پاکدامن رکھنے کے لیے کوشش کی وہ بھی اللہ کے راستے میں ہے اور جس نے مقابلہ بازی کے لیے کوشش کی تو وہ طاغوت (شیطان) کے راستے پر ہے۔“","",{"t":"فی سبیل اللہ کی اقسام","k":"أخرجه البزار: ۱۸۷۱ - الكشف، وأبونعيم في \"الحلية\": ۶/۱۹۶-۱۹۷، والأصبهاني في \"الترغيب والترهيب\": ۴۷/۲ - ۴۸/۱ - مصورة الجامعة الاسلامية الثانية، والبيهقي في \"السنن\": ۹/۲۵، والطبراني في \"الاوسط\"\n(الصحيحة: ۲۲۳۲)","e":"قرآن مجید میں مصارف زکوۃ میں ”فی سبیل اللہ“ سے مراد جہاد ہے، بعض احادیث سے ثابت ہوتا ہے کہ حج بھی اسی ”فی سبیل اللہ“ میں داخل ہیں۔ جیسا کہ سیدنا ابو طلیق نے اس بنا پر اپنی بیوی کو حج کرنے کے لیے اونٹ دینے سے انکار کر دیا تھا کہ اس نے اس کو فی سبیل اللہ یعنی جہاد کے لیے وقف کر دیا تھا، اس وقت آپ صلی اللہ علیہ وسلم نے فرمایا کہ حج بھی فی سبیل اللہ ہے۔ (دیکھئے: صحیحہ: ۳۰۶۹) اس حدیث سے پتہ چلتا ہے کہ لغوی طور پر ہر کار خیر کو فی سبیل اللہ کہا جا سکتا ہے، جیسا کہ اللہ تعالیٰ نے مہاجرین کو ”احصروا فی سبیل اللہ“ کا مصداق ٹھہرایا۔"}],[2138,"طلق بن حبیب بصری سے روایت ہے کہ سیدنا ابو طلیق رضی اللہ عنہ نے ان کو بیان کیا کہ میری بیوی ام طلیق رضی اللہ عنہا میرے پاس آئی اور کہا: ابو طلیق! حج کی تیاری کرو۔ میرے پاس ایک اونٹ اور ایک اونٹنی تھی۔ اونٹنی کو حج کے لیے اور اونٹ کو جہاد کے لیے استعمال کرتا تھا۔ اس نے مجھ سے اونٹ کا مطالبہ کیا تاکہ وہ حج کر سکے۔ میں نے کہا: کیا تو جانتی نہیں کہ میں نے اسے اللہ کی راہ کے لیے وقف کر دیا ہے؟ اس نے کہا: حج بھی اللہ کی راہ میں آتا ہے، اس لیے مجھے دے دے، اللہ تجھ پر رحم کرے۔ میں نے کہا: میں نہیں چاہتا کہ تجھے دوں۔ اس نے کہا: تو پھر مجھے اونٹنی دے دو اور خود اونٹ پر حج کر لو۔ میں نے کہا: میں تجھے خود پر ترجیح نہیں دوں گا۔ اس نے کہا: تو پھر کوئی خرچ مرچ ہی دے دو۔ میں نے کہا: میرے پاس اتنا مال ہے ہی نہیں جو میری اور میرے اہل وعیال کی ضروریات سے زائد ہو۔ اس نے کہا: اگر تو مجھے دے گا تو اللہ تعالیٰ تجھے بہتر بدلہ عطا کرے گا۔ جب میں نے اس کا بھی انکار کیا تو اس نے کہا: جب تو رسول اللہ صلی اللہ علیہ وسلم کے پاس جائے تو آپ کو میرا سلام دینا اور میں نے جو کچھ تجھے کہا، آپ کو بتلا دینا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا، آپ کو اس کا سلام پہنچایا اور اس کی ساری باتیں بتلا دیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ام طلیق سچی ہے، اگر تو اسے اونٹ دے دیتا تو وہ اللہ کی راہ میں ہی ہوتا اور اگر اونٹنی دیتا تو تم دونوں اللہ کی راہ میں ہوتے اور اگر تو اسے کوئی خرچ مرچ دے دیتا تو اللہ تجھے بہترین بدل عطا کرتا۔“ میں نے کہا: اے اللہ کے رسول صلی اللہ علیہ وسلم! وہ آپ سے یہ سوال بھی کر رہی تھی کہ آپ کے پاس کون سا عمل ہے جو حج کرنے کے برابر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”رمضان میں عمرہ کرنا۔“","",{"t":"حج بھی فی سبیل اللہ ہے","k":"أخرجه الدولابي في \"الأسماء والكنى\" ۱/۴۱، ورواه الطبراني في \"الكبير\": ۲۲/۳۲۴/۸۱۶ مطولا و مختصرا، و البزار: ۲/۳۸/۱۱۵۱ مختصرا\n(الصحيحة: ۳۰۶۹)","e":"معلوم ہوا کہ جہاد کی طرح حج بھی فی سبیل اللہ ہے، یہی وجہ ہے کہ سیدنا عبد اللہ بن عباس اور سیدنا عبد اللہ بن عمر رضی اللہ عنہما حج کے لیے زکوۃ دینے کے قائل تھے، کیونکہ مصارف زکوۃ میں ایک مصرف فی سبیل اللہ ہے۔"}],[2139,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”فتنوں کے زمانے میں بہتر آدمی وہ ہو گا جو اپنے گھوڑے کی لگام تھام کر اللہ کے دشمنوں کے تعاقب میں رہے گا، وہ انھیں ڈرائے گا اور وہ اس کو خوفزدہ کریں گے یا وہ آدمی جو کسی ویرانے میں فروکش ہو گا اور اپنے اوپر عائد ہونے والے اللہ تعالیٰ کے حقوق ادا کرتا رہے گا۔“","",{"t":"زمانہ فتن میں بہترین لوگ","k":"أخرجه الحاكم: ۴/۴۴۶\n(الصحيحة: ۶۹۸)","e":"اس حدیث کا تعلق اس پرفتن دور سے ہے کہ جس میں زمانے میں اتنا بگاڑ پیدا ہو جائے کہ دین میں فتنے کا ڈر ہو اور حرام و مشتبہ چیزوں میں مبتلا ہونے کا اندیشہ ہو نیز ان محرمات سے بچ کر ان کا مقابلہ کرنے کی سکت بھی نہ ہو، ایسے حالات میں اللہ تعالیٰ کی عبادت و اطاعت کے لیے گوشہ نشینی اختیار کرنا افضل لوگوں کا کام ہے۔ جیسا کہ سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الْمُسْلِمِ غَنَم يَتْبَعُ بِهَا شَعَفَ الْجِبَالِ وَمَوَاقِعَ القَطْرِ، يَفِرُّ بِدِينِهِ مِنَ الْفِتَنِ .» ..... ”عنقریب ایسا (پرفتن) وقت آئے گا کہ مسلمان کا بہترین مال وہ بکریاں ہوں گی جن کو لے کر وہ پہاڑوں کی چوٹیوں اور بارش کے گرنے کے مقامات (یعنی جنگلوں میں) چلا جائے گا، اس طرح وہ اپنے دین کو فتنوں سے بچا سکے گا۔“ (صحیح بخاری: ۱۹) یاد رہے کہ عام حالات میں اسلام رہبانیت کی اجازت نہیں دیتا کہ مسلمان دنیا سے بھاگ کر جنگلوں اور صحراؤں میں نکل جائے، مسلمان کا کمال اور امتیاز اس میں ہے کہ وہ اپنے جیسے انسانوں میں رہ کر حقوق اللہ اور حقوق العباد کو احسن انداز میں ادا کرے، حق و باطل کی کشمکش اور معرکہ آرائی میں حق کو سر بلند کرنے اور باطل کو نیست و نابود کرنے کے لیے جد و جہد کرے اور اس منہج میں صبر آزما مشکلات کو خندہ پیشانی کے ساتھ برداشت کرے۔"}],[2140,"سیدنا ابوطفیل رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسکرائے اور بہت مسکرائے، پھر فرمایا: ”کیا تم مجھ سے میری مسکراہٹ کے بارے میں دریافت کرو گے؟“ ہم نے کہا: اے اللہ کے رسول! آپ کیوں ہنسے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے اپنی امت کے کچھ لوگ دیکھے، جنھیں زنجیروں میں جکڑ کر جنت کی طرف لے جایا جا رہا ہے، وہ جنت انھیں بڑی ہی نا پسند ہے!“ ہم نے کہا: وہ کون لوگ ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ عجمی لوگ ہیں، مہاجروں نے انھیں قیدی بنا کر اسلام میں داخل کر دیا۔“","",{"t":"کچھ لوگ مجبوراً مشرف باسلام ہوتے ہیں، لیکن......","k":"رواه أبو نعيم في \"أخبار أصبهان\": ۲/۲۹۸، والبزار في مسنده: ۲/۲۸۹/۱۷۳۰، والطبراني\n(الصحيحة: ۲۸۷۴)","e":"امام البانی رحمہ اللہ نے اس حدیث کے مختلف شواہد پیش کرتے ہوئے کہا: سیدنا ابو امامہ رضی اللہ عنہ کہتے ہیں کہ ایک دن نبی کریم ہنس پڑے، آپ سے پوچھا گیا کہ اے اللہ کے رسول! آپ کیوں ہنسے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: «عَجِبْتُ لِأَقْوَامٍ يُسَاقُونَ إِلَى الْجَنَّةِ فِي السَّلَاسِلِ وَهُمْ كَارِهُونَ .» ..... ”مجھے ان لوگوں پر بڑا تعجب ہو رہا ہے، جن کو زنجیروں میں جکڑ کر جنت کی طرف لایا جارہا ہے، جب کہ وہ ناپسند کر رہے ہیں۔“ (احمد: ۵/۲۴۹، ۲۵۶) سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ قَوْمٍ يُقَادُونَ إِلَى الْجَنَّةِ فِي السَّلاسل» ..... ”ہمارے رب نے ان لوگوں پر تعجب کیا ہے، جنہیں زنجیروں میں جکڑ کر جنت کی طرف لایا جا رہا ہے۔“ (صحیح بخاری، بحوالہ صحیحہ: ۲۸۷۴) ان احادیث کا معنی و مفہوم یہ ہے کہ مجاہدین کافر قیدیوں کو زنجیروں اور بیڑیوں میں جکڑ کر دار الاسلام میں لائیں گے، پھر وہ اللہ تعالیٰ کی توفیق سے دائرہ اسلام میں داخل ہو کر جنت کے حقدار بن جائیں گے، گویا کہ یہ لوگ جنت میں داخل نہیں ہونا چاہتے تھے، کیونکہ قیدی بن کر دار الاسلام میں آنا ان کو سخت نا پسند تھا، لیکن ان کی یہ قید ان کی بہشت کا سبب بن گئی۔"}],[2141,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے ایک آدمی کو حکم دیا کہ جب وہ اپنے بستر پر لیٹے تو کہے: اے اللہ! تو نے میری جان کو پیدا کیا ہے اور تو ہی اس کو فوت کرے گا، تیرے لیے ہی اس کا مرنا اور زندہ رہنا ہے۔ اگر تو اس کو زندگی عطا کرے تو اس کی حفاظت کرنا اور اگر موت دے تو بخش دینا۔ اے اللہ! میں تجھ سے عافیت کا سوال کرتا ہوں۔ اس آدمی نے عبد اللہ بن عمر سے پوچھا: کیا تو نے یہ کلمات اپنے باپ عمر رضی اللہ عنہ سے سنے ہیں؟ انھوں نے کہا: عمر سے اعلی شخصیت یعنی رسول اللہ صلی اللہ علیہ وسلم سے سنے ہیں۔","",{"t":"رات کو سوتے وقت کی دعا","k":"أخرجه مسلم: ۸/۷۸، وابن حبان: ۷/۴۲۸/۵۵۱۶، والبيهقي في \"الأسماء والصفات\": ۷۵، وأحمد: ۲/۷۹\n(الصحيحة: ۳۹۹۸)","e":"معلوم ہوا کہ سوتے وقت یہ دعا پڑھنی چاہیے: اَللَّهُمَّ أَنْتَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْلَهَا، اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ"}],[2142,"زیاد بن جبیر بن حیہ کہتے ہیں: مجھے میرے باپ نے بیان کیا کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے ہرمزان سے کہا: تم تو مجھ سے بچ گئے ہو، اب ہماری خیر خواہی تو کرو۔ یہ اس وقت کی بات ہے جب انھوں نے اسے امان دیتے ہوئے کہا: کوئی حرج نہیں، تم بات کر سکتے ہو۔ سو ہرمزان نے کہا: جی ہاں، آج فارس کا ایک سر ہے اور دو بازو۔ سیدنا عمر رضی اللہ عنہ نے کہا: سر کہاں ہے؟ ہرمزان: نہاوند، جو بندار کے ساتھ ہے، اس کے ساتھ کسری کے کمانڈر اور اہل اصفہان بھی ہیں۔ سیدنا عمر رضی اللہ عنہ نے کہا: دو بازو کہاں ہیں؟ ہرمزان: راوی کہتا ہے کہ اس نے جو جگہ ذکر کی تھی، وہ اسے بھول گئی ہے، پھر ہرمزان نے کہا: بازؤوں کو کاٹ دو، تاکہ سر کمزور ہو جائے۔ سیدنا عمر رضی اللہ عنہ نے کہا: اللہ کے دشمن! تو جھوٹ بول رہا ہے، ہم پہلے سر پر چڑھائی کریں گے، اس طرح اللہ تعالیٰ اس کو ملیا میٹ کر دے گا، اگر ایسے ہو گیا تو بازو خود بخود دم توڑ جائیں گے۔ پھر سیدنا عمر رضی اللہ عنہ نے یہ ارادہ کیا کہ وہ جنگ میں بنفس نفیس شرکت کریں۔ لیکن لوگوں نے کہا: اے امیر المؤمنین! ہم آپ کو اللہ تعالیٰ کا واسطہ دیتے ہیں کہ آپ خود عجموں کی طرف نہ جائیں، اگر آپ شہید ہو گئے تو مسلمانوں کا نظام درہم برہم ہو جائے گا، آپ مجاہدین کے لشکروں کو بھیج دیں۔ (آپ نے اسی رائے پر عمل کیا اور) اپنے بیٹے سیدنا عبد اللہ بن عمر، مہاجرین اور انصار سمیت اہل مدینہ کو اہل فارس سے لڑنے کے لیے بھیج دیا۔ اُدھر سیدنا ابوموسی اشعری رضی اللہ عنہ کو خط لکھا کہ وہ اہل بصرہ کو لے کر اور سیدنا حذیفہ بن یمان رضی اللہ عنہ کو خط لکھا کہ وہ اہل کوفہ کو لے کر نہاوند جمع ہو جائیں۔ جب تم سارے جمع ہو جاؤ تو تمہارے امیر سیدنا نعمان بن مقرن مزنی رضی اللہ عنہ ہوں گے۔ جب یہ لشکر نہاوند میں جمع ہوئے تو (عامل کسری) بندار، جو کہ آتش پرست تھا، نے ان کی طرف پیغام بھیجا: عربوں کی جماعت! اپنا قاصد بھیجو تا کہ بات کی جا سکے۔ لوگوں نے سیدنا مغیرہ بن شعبہ رضی اللہ عنہ کا انتخاب کیا۔ جبیر بن حیہ کہتے ہیں: گویا میں اب بھی مغیرہ کو دیکھ رہا ہوں، وہ ایک دراز قد آدمی تھے، ان کے لمبے لمبے بال تھے اور وہ کانے بھی تھے۔ پس وہ چلے گئے اور جب (گفت وشنید کر کے) واپس آئے تو ہم نے پوچھا (کہ کیا کر کے آئے ہو)۔ انھوں نے کہا: آتش پرست نے اپنے ساتھیوں سے مشورہ کیا اور پوچھا: اس عربی کے لیے ہم کیسا ماحول بنائیں؟ کیا حسن و جمال، خوشی و شادمانی اور ملوکیت و بادشاہت والا یا پھر جان بوجھ کر تنگ حالی ظاہر کریں اور دنیوی (آرائشوں اور سہولتوں) سے ذرا دور ہو جائیں؟ انھوں نے کہا: بلکہ ہمیں چاہیے کہ اپنے حسن اور تعداد کی اعلی صورت اختیار کریں۔ (بہر حال میں وہاں پہنچ گیا) کیا دیکھتا ہوں کہ لڑنے کے آلے اور ڈھالیں، بس آنکھیں چندھیا جاتی ہیں، میں نے دیکھا کہ وہ بندار کے پاس کھڑے تھے، جبکہ وہ سونے کے تخت پر بیٹھا ہوا تھا اور اس کے سر پر تاج تھا۔ میں سیدھا آگے نکل گیا اور اس کے ساتھ تخت پر بیٹھنے کے لیے سر جھکایا (جیسے عام بندہ بیٹھنے کی تیاری کرتا ہے)، لیکن مجھے دھکیلا گیا اور میری زجر و توبیخ کی گئی۔ میں نے کہا کہ قاصدوں سے ایسی (بدسلوکی) نہیں کرتے۔ جبکہ انھوں نے مجھے کہا: تو کتا ہے، کیا تو بادشاہ کے ساتھ بیٹھتا ہے؟ میں نے کہا: جتنا تم میں اس کا مقام ہے، میری قوم میں اس سے زیادہ میرا مقام ہے۔ پھر بھی اس نے مجھے ڈانٹا اور کہا: بیٹھ جا۔ میں بیٹھ گیا، (پہلے بادشاہ نے کچھ کہا اور) میرے سامنے اس کی بات کا یوں ترجمہ پیش کیا گیا: او عربوں کی جماعت! تم سب سے زیادہ بھوکے تھے، سب سے بڑے بد بخت تھے، سب سے زیادہ گندے تھے، (ترقی یافتہ سلطنتوں سے) بلکہ ہر خیر سے بہت دور تھے، میں نے تمہیں تیروں میں پرونے والے اپنے کمانڈروں کو حکم دے دینا تھا، لیکن تمہاری گندی اور پلید لاشوں کی وجہ سے ایسے نہیں کیا، اب اگر تم واپس چلے گئے تو ٹھیک اور اگر ایسا کرنے سے انکار کیا تو ہم تمہیں تمہاری قتل گاہوں میں ٹھہرا دیں گے۔ سیدنا مغیرہ رضی اللہ عنہ نے کہا: میں نے اللہ تعالیٰ کی حمد وثنا بیان کی اور کہا: بخدا! تو نے ہمارے صفات بیان کرنے میں کوئی غلطی نہیں کی، ہم (ترقی یافتہ سلطنتوں) سے دور تھے، بھوکے تھے، بد بخت تھے اور ہر بھلائی سے محروم تھے۔ (لیکن ایک ایسا وقت آیا کہ) اللہ تعالیٰ نے ہماری طرف اپنا رسول مبعوث کر دیا، اس نے ہمیں دنیا میں تائید و نصرت اور آخرت میں جنت و بہشت کی خوشخبریاں دیں، اس رسول کی آمد سے لے کر یہاں تمہارے پاس پہنچنے تک ہم اپنے رب سے کامیابی اور مدد وصول کرتے رہے، ٹھیک ہے، تمہارے پاس ایسی بادشاہت اور زندگی ہے، (لیکن یہ ہمارے نزدیک بدبختی ہے) اور ہم اس شقاوت کی طرف کبھی نہیں لوٹیں گے، جب تک تم پر غالب نہ آجائیں یا پھر یہیں شہید نہ ہو جائیں۔ اس نے کہا: کانے (مغیرہ) نے اپنے دل کی بات بیان کر دی اور سچ کہا ہے۔ اس کے بعد میں اس کے پاس سے کھڑا ہوا (اور واپس آ گیا، اللہ کی قسم! میں نے اپنے انداز سے پارسی کو مرعوب کر دیا۔ اس نے ہماری طرف پیغام بھیجا کہ تم (دریا) عبور کر کے آؤ گے یا ہم؟ سیدنا نعمان رضی اللہ عنہ نے کہا: (میرے ساتھیو!) تم عبور کر کے جاؤ، پس ہم (دریا) عبور کر کے پہنچ گئے۔ میرے باپ (جبیر) نے کہا: میں نے ایسا منظر کبھی نہیں دیکھا تھا، آتش پرست فارسیوں کا لشکر یوں لگ رہا تھا، جیسے وہ لوہے کا پہاڑ ہے، انھوں نے عربوں کا مقابلہ کرنے سے فرار نہ ہونے کا عہد و پیمان کر رکھا تھا اور بعض (جنگجوؤں) کو بعض کے ساتھ ملایا گیا تھا، حتی کہ ایک رسی میں سات افراد تھے اور انھوں نے اپنے پیچھے نوک دار لوہا بچھا دیا اور کہنے لگے کہ جو بھی فرار اختیار کرے گا، نوک دار لوہا اسے زخمی کر دے گا۔ سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نے ان کی کثرت کو دیکھ کر کہا کہ (اس جنگ میں کافروں کی جتنی تعداد قتل ہو گی) اتنی تعداد میں نے کبھی نہیں دیکھی، بیشک ہمارا دشمن نیند یا سکون کو ترک کر چکا ہے، اس لیے جلدی کرنے کی ضرورت نہیں۔ بہر حال اگر میں امیر ہوتا تو ان کے ساتھ تیزی کے ساتھ مقابلہ کرتا۔ سیدنا نعمان رضی اللہ عنہ بہت زیادہ رونے والے شخص تھے، انھوں نے مجھے کہا: اللہ تجھے اس قسم کے حالات میں حاضر کرے گا، (اس وقت دیکھ لینا کہ کیا کرنا ہے)۔ اب تیرا جو مقام ہے، اس پر تجھے پریشان ہونا چاہیے نہ اسے معیوب سمجھنا چاہیے۔ اللہ تعالیٰ کی قسم! مجھے ان کے ساتھ لڑائی کرنے میں عجلت سے مانع چیز آپ صلی اللہ علیہ وسلم کی حدیث ہے، جب آپ صلی اللہ علیہ وسلم کسی غزوہ میں تشریف لے جاتے تو دن کے شروع میں لڑائی نہ کرتے، بلکہ ٹھہر تے حتی کہ نماز کا وقت حاضر ہو جاتا (یعنی سورج ڈھل جاتا)، ہوائیں چلنا شروع ہو جاتیں اور لڑنا خوشگوار ہو جاتا۔ پھر سیدنا نعمان رضی اللہ عنہ نے کہا: اے اللہ! میں تجھ سے سوال کرتا ہوں کہ جس فتح میں اسلام اور اہل اسلام کی عزت اور کفر اور اہل کفر کی ذلت ہو، اس کے ذریعے میری آنکھوں کو ٹھنڈا کر دینا اور اس کے بعد مجھے شہادت عطا کر دینا۔ پھر کہا: آمین کہو، پس ہم نے آمین کہی۔ پھر وہ رونے لگ گئے اور ہم بھی روئے۔ پھر سیدنا نعمان نے کہا: جب میں پہلی دفعہ جھنڈا ہلاؤں گا تو اپنا اسلحہ تھام لینا، جب دوسری دفعہ ہلاؤں تو دشمن سے لڑنے کے لیے تیار ہو جانا اور جب تیسری دفعہ ہلاؤں تو ہر کوئی اللہ تعالیٰ کی برکت کے ساتھ اپنے قریبی دشمن پر حملہ کر دے۔ جب (ظہر کی) نماز کا وقت ہوا اور ہوائیں چل پڑیں تو انھوں نے اللہ اکبر کہا، ہم نے بھی اللہ اکبر کہا۔ پھر انھوں نے کہا: اللہ کی قسم! ان شاء اللہ فتح کی ہوا چل پڑی ہے اور مجھے امید ہے کہ اللہ تعالیٰ میری دعا قبول کر کے ہمیں فتح عطا کرے گا۔ پھر انھوں نے پہلی دفعہ جھنڈا ہلایا، پھر دوسری دفعہ ہلایا اور جب تیسری دفعہ اسے حرکت دی تو ہم میں سے ہر ایک اپنے قریبی دشمن پر ٹوٹ پڑا۔ سیدنا نعمان رضی اللہ عنہ نے کہا: اگر میں شہید ہو جاؤں تو حذیفہ بن یمان امیر لشکر ہوں گے، اگر وہ بھی شہید ہو جائیں تو فلاں ہوں، ان کے بعد فلاں، حتی کہ انھوں نے سات امیروں کا ذکر کیا، آخر میں سیدنا مغیرہ بن شعبہ رضی اللہ عنہ کا ذکر کیا۔ میرے باپ (جبیر) نے کہا: اللہ کی قسم! میرے علم کے مطابق ہر مسلمان یہ چاہتا تھا کہ یا تو وہ شہید ہو جائے یا پھر فتحیاب، دشمن بھی ہمارے مقابلے میں ڈٹے رہے، ہمیں صرف لوہے کی لوہے پر پڑنے کی آواز آتی تھی، بالآخر ایسے ہوا کہ مسلمانوں کی بہت بڑی تعداد شہید ہو گئی، لیکن جب انھوں نے ہمارا صبر اور عزم دیکھا کہ ان لوگوں کا فرار ہونے کا کوئی ارادہ نہیں ہے تو وہ شکست کے لیے تیار ہو گئے، جب ایک مجاہد کسی ایک دشمن پر حملہ آور ہوتا تو وہ ایک رسی میں باندھے ہوئے ساتوں کے سات اس پر ٹوٹ پڑتے، لیکن ہوتا یوں کہ سارے کے سارے قتل ہو جاتے، پیچھے سے نوکیلا لوہا ان کو زخمی کرتا۔ سیدنا نعمان رضی اللہ عنہ نے کہا: جھنڈا آگے بڑھاؤ، پس ہم نے جھنڈا آگے بڑھانا اور ان کو قتل کرنا شروع کر دیا اور وہ شکست کھانا شروع ہو گئے۔ جب سیدنا نعمان رضی اللہ عنہ نے دیکھا کہ اللہ تعالیٰ نے ان کی دعا قبول کر لی ہے اور فتح عطا کی ہے، اسی اثنا میں ایک تیر آیا اور ان کی کوکھ میں پیوست ہو گیا اور وہ شہید ہو گئے۔ ان کے بھائی معقل بن مقرن نے ان کو کپڑے سے ڈھانپ لیا اور جھنڈا خود تھام لیا اور آگے بڑھا اور کہا: اللہ تم پر رحم کرے، پیش قدمی جاری رکھو، سو ہم نے ایسے ہی کیا اور ان کو شکست دینا اور ان کو قتل کرنا شروع کر دیا۔ جب ہم فارغ ہوئے تو لوگ جمع ہو کر پوچھنے لگے کہ امیر کہاں ہے؟ معقل نے کہا: یہ تمہارا امیر ہے، اللہ تعالیٰ نے فتح عطا کر کے ان کی آنکھوں کو ٹھنڈا کر کے ان کو شہادت سے ہمکنار کر دیا۔ لوگوں نے سیدنا حذیفہ بن یمان رضی اللہ عنہ کی بیعت کر لی۔ اُدھر سیدنا عمر بن خطاب رضی اللہ عنہ مدینہ منورہ میں دعا کرنے میں مگن اور حاملہ کے چیخنے کی طرح منتظر تھے۔ سیدنا حذیفہ رضی اللہ عنہ نے ان کو فتح کا پیغام پہنچانے کے لیے خط لکھا اور ایک مسلمان کے ہاتھ بھیج دیا۔ جب وہ پہنچا تو یوں فتح کا پیغام سنایا: امیر المؤمنین! خوش ہو جاؤ، فتح ہوئی ہے اور اللہ تعالیٰ نے اسلام اور اہل اسلام کو عزت دی ہے اور شرک اور مشرکوں کو ذلیل کر دیا ہے۔ سیدنا عمر رضی اللہ عنہ نے پوچھا: کیا تجھے نعمان نے بھیجا ہے؟ اس نے کہا: امیر المؤمنین! نعمان کی وفات پر ثواب کی توقع کے ساتھ صبر کرو۔ یہ سن کر آپ نے رونا اور انا للہ پڑھنا شروع کر دیا اور کہا: تو ہلاک ہو جائے، تو پھر امیر کا کیا بنا؟ اس نے کہا: فلاں تھا، فلاں تھا، پھر اس نے کچھ نام لینے کے بعد کہا: امیر المؤمنین! اور لوگ بھی ہیں، لیکن آپ ان کو نہیں جانتے۔ سیدنا عمر رضوان اللہ علیہ نے کہا، جبکہ وہ خود رو رہے تھے: اگر عمر نہیں جانتا تو کوئی حرج نہیں، اللہ تعالیٰ تو جانتا ہے۔","",{"t":"جہاد کا آغاز کرنے کا بہترین وقت اور واقعہ نہاوند فاروقی سپاہ سرزمین ایران میں","k":"أخرجه ابن جرير الطبري في \"التاريخ\": ۲/۲۳۳-۲۳۵، وابن حبان: ۱۷۱۲-الموارد، واخرجه البخاري: ۳۱۵۹، ۳۱۶۰ مختصرا وفيه زيادة \"والجناح قیصر\"، وروى منه احمد و غيره حديث الترجمة، يعني لفظ: كان اذا غزا فلم يقاتل اول النهار لم يعجل حتى تحضر الصلوات، وتهب الارواح، ويطيب القتال.\n(الصحيحة: ۲۸۲۶)","e":"اس میں نہاوند کی جنگ کا ذکر ہے، جو قادسیہ کے بعد دوسری فیصلہ کن جنگ تھی، اسے مُؤَرِّخین فتح الفتوح کا نام دیتے ہیں، فاروقی عہد خلافت میں اس میں سیدنا نعمان بن مقرن رضی اللہ عنہ کی قیادت میں پندرہ ہزار مسلمانوں نے ڈیڑھ لاکھ ایرانی مجوسیوں کے جم غفیر کو شکست دی، اس کے بعد اہل فارس کبھی بھی اتنا بڑا لشکر اکٹھا نہ کر سکے۔ ہرمزان: یہ فارس کا ایک کمانڈر تھا، تستر کے موقع پر مسلمانوں کے خلاف بہت زیادہ لڑنے کے بعد سیدنا عمر رضی اللہ عنہ کے حکم پر اتر آیا اور سیدنا ابوموسی اشعری رضی اللہ عنہ نے اس کو قید کر کے سیدنا انس رضی اللہ عنہ کے ساتھ سیدنا عمر رضی اللہ عنہ کے پاس بھیج دیا۔ اس نے اسلام قبول کر لیا تھا، سیدنا عمر رضی اللہ عنہ اس کو قریب کرتے اور اس سے مشورہ لیتے تھے۔ عِلج: اس کی جمع عُلوج ہے، اس کے معانی یہ ہیں: قوی، موٹا تازہ آدمی، عجمی، کافر، مجوسی، گبر، آتش پرست، پارسی لوگ۔"}],[2143,"سیدنا ابوموسی رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”بیشک کسی غزوہ کے دوران اشعری لوگوں (میں سے) جب بعض لوگ بے توشہ ہونے لگتے ہیں یا مدینہ میں ان کے اہل وعیال کا کھانا کم ہونے لگتا ہے تو جس کے پاس جو کچھ ہوتا ہے، وہ سارا ایک کپڑے میں جمع کر لیتے ہیں، پھر ایک برتن کے ذریعے برابر برابر آپس میں تقسیم کر لیتے ہیں، یہ لوگ مجھ میں سے ہیں اور میں ان میں سے ہوں۔“","",{"t":"اشعری لوگوں کا ایثار","k":"أخرجه البخاري: ۲۴۸۶، ومسلم: ۷/۱۷۱، والبيهقي: ۱۰/۱۳۲، والبغوي في \"شرح السنة\": ۱۰/۲۱۵\n(الصحيحة: ۳۵۰۴)","e":"اس حدیث میں اشعری لوگوں کے ایثار کی بہت بڑی مثال بیان کی گئی ہے۔"}],[2144,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”روزِ قیامت جن لوگوں کا سب سے پہلے فیصلہ کیا جائے گا (وہ یہ ہیں:) (۱) وہ آدمی جو شہید ہوا، اسے لایا جائے گا، اللہ تعالیٰ اپنی نعمتوں کا تعارف کروائے گا اور وہ اقرار کرے گا، پھر اللہ تعالیٰ پوچھے گا: تو نے کون سا عمل کیا ہے؟ وہ کہے گا: میں نے تیری خاطر لڑائی کی، حتی کہ شہید ہو گیا۔ اللہ تعالیٰ فرمائے گا: تو جھوٹ بولتا ہے، تو تو اس لیے لڑا تھا تا کہ تجھے بہادر کہا جائے، اور وہ کہا جا چکا ہے، پھر اس کے بارے میں حکم ہو گا اور اسے چہرے کے بل گھسیٹ کر جہنم میں ڈال دیا جائے گا۔ (۲) وہ آدمی، جس نے علم سیکھا اور سکھایا اور قرآن مجید پڑھا، اسے لایا جائے گا، اللہ تعالیٰ اسے اپنی نعمتوں کا تعارف کروائیں گے، وہ اقرار کرے گا۔ پھر اللہ تعالیٰ پوچھے گا: کون سا عمل کر کے آیا ہے؟ وہ کہے گا: میں نے تیری خاطر علم سیکھا اور سکھایا اور قرآن مجید پڑھا۔ اللہ تعالیٰ فرمائے گا: تو جھوٹا ہے، تو نے تو علم اس لیے حاصل کیا تھا تا کہ تجھے عالم کہا جائے اور قرآن مجید پڑھا، تا کہ تجھے قاری کہا جائے اور وہ کہہ دیا گیا۔ پھر اس کے بارے میں حکم دیا جائے گا اور اسے چہرے کے بل گھسیٹ کر آگ میں پھینک دیا جائے گا۔ (۳) وہ آدمی، جسے اللہ تعالیٰ نے رزق میں فراوانی دی اور ہر قسم کا مال عطا کیا۔ اس کو لایا جائے گا، اللہ تعالیٰ اپنی نعمتوں کا تعارف کروائیں گے، وہ اقرار کر لے گا۔ پھر اللہ تعالیٰ پوچھے گا: تو کون سا عمل کر کے لایا ہے؟ وہ کہے گا: میں نے ہر اس مصرف میں مال خرچ کیا جہاں خرچ کرنا تجھے پسند تھا۔ اللہ تعالیٰ فرمائے گا: تو جھوٹا ہے، تو نے تو اس لیے کیا تھا تا کہ تجھے سخی کہا جائے اور وہ کہہ دیا گیا۔ پھر اس کے بارے میں حکم دیا جائے گا اور چہرے کے بل گھسیٹ کر جہنم میں پھینک دیا جائے گا۔“","",{"t":"شہید، عالم، قاری اور سخی، جو کہ ریا کار تھے","k":"أخرجه مسلم: ۶/۴۷، والنسائي: ۲/۵۸، و الحاكم: ۱/۱۰۷، ۲/۱۱۰، والبيهقي: ۹/۱۶۸، وأبونعيم في \"الحلية\": ۲/۱۹۲، والخطيب في \"تقييد العلم: ۱۹۷، وأحمد: ۲/۳۲۲\n(الصحيحة: ۳۵۱۸)","e":"بڑے بڑے نیک اعمال کو سر انجام دینے میں سب سے مشکل مرحلہ نیت کا ہے۔ عبد اللہ بن مبارک نے کہا: رُبَّ عَمَلٍ صَغِيْرِ تُعَظِمَهُ النَّيَّةُ، وَرُبَّ عَمَلٍ كَبِيْرِ تُصَعِرِهِ النَّيِّةُ ..... بہت سے چھوٹے اعمال کو نیت بڑا کر دیتی ہے اور بہت سے بڑے اعمال کو نیت چھوٹا کر دیتی ہے۔ نیت، اعمال صالحہ کی بنیاد ہے، اس لیے اس کو درست کرنے کے لیے سنجیدگی کی ضرورت ہے، اس نقطے پر بار بار غور کیا جائے کہ عمل کرنے کا ہمارا مقصد کیا ہے۔"}],[2145,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”غزوے کی دو قسمیں ہیں: (۱) جس نے (جہاد کر کے) اللہ کی رضامندی تلاش کی، حکمران کی اطاعت کی، عمدہ مال خرچ کیا اور فساد سے اجتناب کیا تو اس کا سونا اور جاگنا سب عبادت ہے اور (۲) جس نے فخر کرتے ہوئے، ریا کاری کرتے ہوئے اور شہرت کے حصول کے لیے (جہاد کیا)، حکمران کی نافرمانی کی اور زمین میں فساد برپا کیا تو وہ برابر سرابر بھی نہیں لوٹے گا۔“","",{"t":"شہید، عالم، قاری اور سخی، جو کہ ریا کار تھے","k":"أخرجه ابوداود: ۲۵۱۵، والنسائي في السير\" من الكبرى\": ۲/۵۲/۱\n(الصحيحة: ۱۹۹۰)","e":"برابر سرابر نہ لوٹنے سے مراد یہ ہے کہ واپسی پر نیکیوں کے بجائے برائیوں کا بوجھ ہوتا ہے۔"}],[2146,"سیدنا ابو فاطمہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تو ہجرت کر، اس کی کوئی مثال نہیں۔ تو روزوں کا اہتمام کر، وہ بے مثال عبادت ہے اور سجدے کیا کر، کیونکہ جب بھی تو سجدہ کرتا ہے تو اللہ تعالیٰ تیرا ایک درجہ بلند کرتا ہے اور ایک گناہ معاف کر دیتا ہے۔“","",{"t":"ہجرت بے نظیر عمل ہے","k":"رواه الطبراني في \"الكبير\": كما في الجامع الصغير \" و \" الكبير \": للسيوطي، من حديث ابي فاطمة، ولم اقف على اسناده، ولا على من تكلم عليه بتصحيح او تضعيف، وقد استطعت الوقوف على الحديث كله الا فقرة الجهاد المحذوفة وهى عليك بالجهاد فانه لا مثله له))، مفرقا في عدة مصادر- ثم بين الالباني رحمہ اللہ هذه المصادر\n(الصحيحة: ۱۹۳۷)","e":"اصطلاح میں دار الکفر سے دار الاسلام کی طرف منتقل ہونا ”ہجرت“ کہلاتا ہے، یہ واحد عمل ہے کہ جس کے ذریعے مسلمان برے ماحول سے نکل کر نیک ماحول تک رسائی حاصل کرنے کے لیے گھر بار، مال و جائداد اور بسا اوقات اپنے بیوی بچے اور عزیز و قریب بھی چھوڑ دیتا ہے، اولین مہاجرین کی مثالیں ہمارے سامنے ہیں۔ اگر چہ عصر حاضر میں دیارِ کفر دنیوی سہولتوں اور آرائشوں کے اعتبار سے جنت کا سماں پیش کر رہے ہیں، بہر حال مومن کو دار الاسلام کا ہی انتخاب کرنا چاہیے۔"}],[2147,"سیدنا جنادہ بن ابوامیہ رضی اللہ عنہ کہتے ہیں کہ (ایک دفعہ) صحابہ کرام رضی اللہ عنہم ایک دوسرے سے کہنے لگے کہ ہجرت کا سلسلہ ختم ہو چکا ہے، اس بارے میں ان کی آرا میں اختلاف نظر آنے لگا۔ میں نبی کریم صلی اللہ علیہ وسلم کے پاس گیا اور کہا: اے اللہ کے رسول! کچھ لوگ کہتے ہیں کہ ہجرت منقطع ہو چکی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تک جہاد باقی ہے، ہجرت کا سلسلہ ختم نہیں ہو سکتا۔“","",{"t":"ہجرت اور جہاد لازم و ملزوم ہیں","k":"أخرجه الطحاوي في \"مشكل الآثار\": ۳/۲۵۷، وأحمد: ۴/۶۲ و ۵/۳۷۵\n(الصحيحة: ۱۶۷۴)","e":"اس حدیث کا مطلب یہ ہوا کہ اسلام کی بقا تک جہاد اور ہجرت کا حکم باقی ہے۔"}],[2148,"زوجہ رسول سیدہ ام سلمہ رضی اللہ عنہا کہتی ہیں کہ جب مکہ (کی سرزمین) ہم پر تنگ ہو گئی، اصحاب رسول کو تکالیف دی گئیں اور انھیں آزمایا گیا اور انھوں نے دیکھا کہ ہم اپنے دین کی وجہ سے جن آزمائشوں اور فتنوں میں مبتلا ہیں، (فی الحال) رسول اللہ صلی اللہ علیہ وسلم ان کو رفع دفع نہیں کر سکتے اور خود رسول اللہ صلی اللہ علیہ وسلم کو اپنی قوم اور چچا کی وجہ سے طاقت و عزت حاصل تھی، اس لیے آپ مکروہات، جن میں عام صحابہ مبتلا تھے، سے محفوظ تھے۔ (ایک دن) رسول اللہ صلی اللہ علیہ وسلم نے انھیں فرمایا: ”حبشہ میں ایک بادشاہ ہے، اس کی سلطنت میں کسی پر ظلم نہیں کیا جاتا، تم لوگ اس سے جا ملو حتی کہ اللہ تعالیٰ ان مصائب سے کشادگی اور راہ فرار کی کوئی صورت پیدا کر دے۔“ ہم نے اس تجویز پر عمل کیا اور گروہوں کی شکل میں (مکہ سے) نکل پڑے اور ایک بہترین مقام پر اور بہترین پڑوسی کے پاس اکٹھے ہو گئے، اس نے ہم کو ہمارے دین پر امان دی اور ہمیں اس کی طرف سے کسی قسم کے ظلم کا اندیشہ نہ رہا۔ ..... راوی نے طویل حدیث ذکر کی، اسی طرح یہ روایت سنن میں ہے اور چار صفحات میں مکمل روایت بیان کی ہے۔","",{"t":"ہجرت حبشہ","k":"أخرجه البيهقي في \"السنن\": ۹/۹ (وقد ساقه بطوله في اربع صفحات) و في \"الدلائل\": ۲/۳۰۱، واحمد: ۱/۲۰۱، ۵/۲۹۰\n(الصحيحة: ۳۱۹۰)","e":"حبشہ کا بادشاہ ایک انصاف پسند حکمران تھا۔ مکی دور میں صحابہ کرام نے مشرکین مکہ کے ظلم و ستم سے تنگ آ کر اور آپ صلی اللہ علیہ وسلم کی اجازت سے حبشہ کی طرف دو ہجرتیں کیں، پہلی ہجرت میں بارہ مرد اور چار خواتین، جبکہ دوسری ہجرت میں بیاسی یا تراسی مرد اور اٹھارہ خواتین تھیں۔"}],[2149,"سیدنا زبیر بن عوام رضی اللہ عنہ کہتے ہیں: خالد بن حزام نے حبشہ کی سرزمین کی طرف ہجرت کی، راستے میں ایک سانپ نے اسے ڈسا اور وہ فوت ہو گیا، پس یہ آیت نازل ہوئی: ﴿اور جو کوئی اپنے گھر سے اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی طرف نکل کھڑا ہوا، پھر اسے موت نے آ پکڑا تو یقیناً اس کا اجر اللہ تعالیٰ کے ذمہ ثابت ہو گیا اور اللہ تعالیٰ بڑا بخشنے والا مہربان ہے۔﴾ (سورۂ نساء: ۱۰۰) زبیر بن عوام کہتے ہیں کہ مجھے ان کی توقع تھی اور حبشہ میں میں ان کے آنے کا انتظار کر رہا تھا، جب مجھے ان کی وفات کی خبر ملی تو میں رنج وغم میں مبتلا ہو گیا، کیونکہ جو بھی قریش سے ہجرت کر کے گیا، اس کے ساتھ کوئی نہ کوئی بیوی بچہ یا رشتہ دار ہوتا تھا اور میرے ساتھ بنو اسد بن عبد العزی قبیلے کا کوئی آدمی نہ تھا اور نہ مجھے اس کے علاوہ کسی کی امید تھی۔","",{"t":"سفر ہجرت میں فوت ہونے والے کی فضیلت","k":"أخرجه ابن أبي حاتم في التفسير: ۲/۱۷۵/۱، وأخرجه ابو نعيم في المعرفة: ۱/۲۰۹/۲ دون قول الزبير: وكنت أتوقعه..... الخ.\n(الصحيحة: ۳۲۱۸)","e":"اس میں اس شخص کی فضیلت کا ذکر ہے، جو اللہ تعالیٰ کے لیے ہجرت کرتا ہے اور اس سفر کے دوران وفات پا جاتا ہے۔ سیدنا زبیر بن عوام اور سیدنا خالد بن حزام رضی اللہ عنہما دونوں کا تعلق بنو اسد سے تھا، اس لیے اول الذکر رنج و غم میں مبتلا ہو گئے تھے۔"}],[2150,"سیدنا برا بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”اگر تم پر رات کو اچانک حملہ کر دیا جائے تو تمھارا شعار (تعارف کرانے کے لیے نشانِ خاص) ”حم لَا يُنْصَرُونَ“ (حم۔ کافروں کی مدد نہیں کی جائے گی۔) ہونا چاہیے۔“","",{"t":"دوران قتال شعار","k":"هو من حديث البراء بن عازب رضي الله عنه، يرويه أبو أسحاق عمرو بن عبدالله السبيعي، وقد اختلف عليه في أسناده علي وجوه: الأول: سفيان عنه عن المهلب بن أبي صفرة، فأخرجه أبو داود: ۲۵۹۷، والترمذي: ۱۶۷۲، وابن الجارود في \"المنتقي\": ۳۵۵/۱۰۶۳، والحاكم ۲/۱۰۷ الوجه الثانية: شيبان عن أبي أسحاق عن البراء: فأخرجه النسائي: ۶۱۵ الوجه الثلاث ..... أخرجه النسائي\n(الصحيحة: ۳۰۹۷)","e":"شعار وہ علامت ہے، جس کے ذریعے شبہ پڑ جانے کی صورت میں مجاہد دوران جنگ اپنے لشکر کے افراد کو پہچان سکتا ہے۔ آپ صلی اللہ علیہ وسلم کے زمانے میں ”آمتْ آمِتْ“ (مار، مار) کے الفاظ کو بھی بطورِ شعار استعمال کیا گیا۔ (ابو داود)"}],[2151,"سیدنا ابوحمید ساعدی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بروز اتوار نکلے اور ثنیہ وداع کو عبور کر گئے، آپ کو ہتھیاروں سے لیس ایک لشکر نظر آیا۔ آپ صلی اللہ علیہ وسلم نے پوچھا: ”یہ کون لوگ ہے۔“ صحابہ نے کہا: یہ عبد اللہ بن ابی بن سلول ہے، جو سیدنا عبد اللہ بن سلام کے قبیلے بنو قینقاع کے چھ سو یہودی رفقا کے ہمرا ہے۔ آپ صلی اللہ علیہ وسلم نے پوچھا: ”آیا یہ لوگ مسلمان ہو گئے ہیں؟“ انھوں نے کہا: نہیں، اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا: ”ان سے کہو کہ لوٹ جاؤ، میں مشرکوں کے خلاف مشرکوں سے مدد طلب نہیں کرتا۔“","",{"t":"مشرکوں سے معاونت نہ لی جائے","k":"أخرجه ابن سعد: ۲/۴۸، والطحاوي في \"المشكل\": ۳/۲۴۱، والطحاوي: ۳/۲۳۹، واحمد: ۳/۴۵۴، والحاكم: ۲/۱۲۱\n(الصحيحة: ۱۱۰۱)","e":"دیگر احادیث سے بھی معلوم ہوتا ہے کہ آپ صلی اللہ علیہ وسلم نے مشرکوں کی مدد قبول نہیں کی، لیکن اس کے برعکس آپ صلی اللہ علیہ وسلم کی زندگی میں ایسے واقعات بھی موجود ہیں، جن میں آپ صلی اللہ علیہ وسلم نے مشرکوں سے مدد لی، مثال کے طور پر حنین کے دن آپ صلی اللہ علیہ وسلم نے صفوان بن امیہ سے مدد لی، اسی طرح فتح مکہ کے سال بنو خزاعہ کے لوگ حالتِ شرک میں قریش کے خلاف آپ صلی اللہ علیہ وسلم کے ساتھ نکلے تھے۔ بہتر یہ ہے کہ نسخ کا دعویٰ کرنے کے بجائے ان احادیث کو اس طرح جمع کیا جائے جہاں ضرورت ہے یا کوئی مشرک حسن الرائے ہو تو ان سے مدد لی جا سکتی ہے، بصورتِ دیگر اجتناب کرنا چاہیے۔"}],[2152,"سیدنا بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کسی غزوے کے لیے نکلے۔ جب واپس آئے تو ایک سیاہ رنگ کی لڑکی آپ صلی اللہ علیہ وسلم کے پاس آئی اور کہا: اے اللہ کے رسول! میں نے نذر مانی تھی کہ اگر اللہ تعالیٰ نے آپ کو عافیت و سلامتی کے ساتھ لوٹایا تو میں آپ کے سامنے دف بجاؤں گی اور گاؤں گی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر تو نے (واقعی) نذر مانی ہے تو دف بجائے، وگرنہ نہیں۔“ اس نے دف بجانا شروع کر دیا۔ سیدنا ابو بکر رضی اللہ عنہ تشریف لائے وہ بجاتی رہی، سیدنا علی رضی اللہ عنہ تشریف لائے وہ بجاتی رہی، پھر سیدنا عثمان رضی اللہ عنہ تشریف لائے وہ بجاتی رہی۔ پھر سیدنا عمر رضی اللہ عنہ تشریف لائے تو اس نے اپنے سرین کے نیچے دف رکھ دیا اور اس پر بیٹھ گئی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے عمر! شیطان تجھ سے ڈرتا ہے، میں بیٹھا ہوا تھا یہ دف بجاتی رہی، ابو بکر آئے یہ بجاتی رہی، پھر علی آئے یہ بجاتی رہی، پھر عثمان آئے یہ بجاتی رہی۔ عمر! جب تم داخل ہوئے تو اس نے دف رکھ دیا۔“","",{"t":"فتح پر دف بجانے کی نذر پوری کرنا","k":"أخرجه الترمذي: ۳۶۹۱، وابن حبان: ۴۳۷۱الأحسان، والبيهقي: ۱۰/۷۷، أحمد: ۵/۳۵۳\n(الصحيحة: ۲۲۶۱)","e":"امام البانی رحمہ اللہ رقمطراز ہیں: یہ بات تو معروف ہے کہ دف، موسیقی اور ساز کے ان آلات میں سے ہے، جو شریعت اسلامیہ میں حرام ہیں اور فقہائے اربعہ سمیت بڑے بڑے ائمہ اس کی حرمت پر متفق ہیں، اس موضوع پر صحیح احادیث پائی جاتی ہیں، البتہ شادی بیاہ اور عیدین کے موقع پر صرف دف بجانے کی اجازت دی گئی ہے، سوال یہ پیدا ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس عورت کو دف بجانے کی نذر پوری کرنے کی اجازت کیوں دی، حالانکہ اللہ تعالیٰ کی نافرمانی میں مانی گئی نذر پوری نہیں کی جاتی؟ اس کا جواب یہ ہے کہ اس نذر کا تعلق اس خوشی سے تھا، جو اس کو نبی کریم صلی اللہ علیہ وسلم کے فاتح اور سالم لوٹنے سے نصیب ہوئی تھی، اس لیے آپ صلی اللہ علیہ وسلم نے اس کو شادی اور عیدین کے موقع پر بجائے جانے والے دف کی اجازت دی، اور بلاشک وشبہ آپ صلی اللہ علیہ وسلم کا غزوے سے کامیابی و کامرانی کے ساتھ لوٹنے کی خوشی اتنی بڑی ہے کہ اس کو شادی اور عید کی خوشی پر تو قیاس ہی نہیں کیا جا سکتا، اس لیے اس حکم کو آپ صلی اللہ علیہ وسلم کے ساتھ خاص سمجھا جائے گا اور کسی دوسرے کے معاملے کو اس پر قیاس نہیں کیا جائے گا، کیونکہ یہ لوہاروں کو فرشتوں پر قیاس کرنے والی بات ہوگی۔ امام خطابی نے (معالم السنن) میں اور علامہ صدیق حسن خان نے (الروضة الندية: ۲/۱۷۷-۱۷۸) میں جمع و تطبیق کی یہی صورت ذکر کی۔ (صحیحہ: ۲۲۶۱)"}],[2153,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بیشک مومن اپنے شیطانوں کو اس طرح تھکا دیتا ہے، جس طرح تم میں سے ایک آدمی سفر میں اپنے اونٹ کو تھکا دیتا ہے۔“","",{"t":"مومن، شیطانوں کو تھکا دیتا ہے","k":"أخرجه أحمد: ۲/۳۸۰\n(الصحيحة: ۳۵۸۶)","e":"مومن، اعمال صالحہ کو سر انجام دینے میں مصروف رہتا ہے، کھانے پینے سے پہلے اور گھر میں داخل ہونے سے پہلے جیسے امور میں اللہ تعالیٰ کا نام لیتا ہے، جس کی وجہ سے اس کے ماکولات و مشروبات میں شیطان کا کوئی حصہ نہیں رہتا اور نہ شیطان اس کے گھر رات گزار سکتا ہے، علاوہ ازیں شیطانی خواہشات اور وساوس اس پر کارگر ثابت نہیں ہوتے، نتیجہ یہ نکلتا ہے کہ شیطان اپنی تمام کارروائیوں میں ناکام اور ضعیف اور مغلوب ہو جاتا ہے۔ اللہ تعالیٰ کے اوامر کی پاسداری، اس کی نواہی سے اجتناب اور نفسانی شہوات سے دوری کی وجہ سے شیطان کی حیثیت قیدی اور مجبور سے زیادہ نہیں رہتی، بلکہ وہ اس جانور کی طرح ہو جاتا ہے، جس کو سفروں نے کمزور اور لاغر کر دیا ہو۔"}],[2154,"سیدنا عدی بن حاتم رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے لیے حیرہ (مقام) کو کتوں کی کیلیوں سے تشبیہ دی گئی اور عنقریب تم اسے فتح کر لو گے۔“ ایک آدمی کھڑا ہوا اور کہا: اے اللہ کے رسول! بنتِ بقیلہ مجھے عطا کر دیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ اسے دے دو۔“ اس کے باپ نے آ کر کہا: ”کیا تو مجھے وہ فروخت کر دے گا؟ اس نے کہا: جی ہاں۔ اس نے پوچھا: کتنی قیمت میں؟ اس نے کہا: من مانی کروں گا اور ایک ہزار درہم (کے عوض فروخت کروں گا)۔ اس نے کہا: میں نے خرید لی ہے۔ کہا گیا کہ اگر میں تیس ہزار کہتا تو؟ اس نے کہا: بھلا ہزار سے بڑا کوئی عدد ہے؟","",{"t":"حیرہ مقام کی فتح کی پیشین گوئی","k":"أخرجه ابن حبان في \"صحيحه\": ۱۷۰۹، وابن أبي عاصم في \"الوحدان\": ق ۲۶۹/۱، والطبراني في \"الكبير\": ۱۷/۸۱/۱۸۳ بلفظ \"اخوها\" مكان \"ابوها\"، والبيهقي في \"السنن\": ۹/۱۳۶\n(الصحيحة: ۲۸۲۵)","e":"حیرہ، لخمی بادشاہوں کا دار الحکومت تھا، جس کے آثار عراق میں کوفہ اور نجف کے درمیان پائے جاتے ہیں، آغازِ اسلام کے وقت یہاں نسطوری عیسائی آباد تھے۔ جب سیدنا خالد بن ولید رضی اللہ عنہ اپنا لشکر لیے بحری اور بری راستے اغمیشیا روانہ ہوئے، ان کے خَورَنق پہنچنے سے پہلے تمام اسلامی دستے اکٹھے ہو گئے۔ ادھر حیرہ کے مرزبان آزاد، غریّین اور قصر ابیض کے درمیان ڈیرے ڈالے ہوئے تھا۔ جب اسے خالد کے قریب آنے کی خبر ملی تو وہ پسپا ہو گیا اور دریائے فرات کے پار چلا گیا اور حیرہ کے عربوں کو وہیں چھوڑ گیا، ان لوگوں کے چار بڑے قلعے تھے۔ ان قلعوں کے ارد گرد جنگ جاری رہی اور ان پر ہر طرف سے یورش کی گئی حتی کہ انھوں نے جزیہ اور مسلمانوں کی حفاظت میں آنے کی شرط پر صلح کر لی۔ یہ واقعہ ربیع الاول ۱۲ھ کو پیش آیا۔"}],[2155,"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب مجھ پر میری امت کے مفتوحہ علاقے پیش کیے گئے تو میں بڑا خوش ہوا۔ اللہ تعالیٰ نے یہ آیت نازل کی: ﴿اور آخرت تیرے لیے دنیا سے بہتر ہے۔ اور تجھے تیرا رب بہت جلد (انعام) دے گا اور تو راضی (خوش) ہو جائے گا۔﴾ (سورۂ ضحیٰ: ۴، ۵) اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو جنت میں موتیوں کے ایک ہزار محلات دیے ہیں، جن کی مٹی کستوری ہے اور ہر ایک محل میں وہی کچھ ہے جو اسے چاہتا ہے۔“","",{"t":"آخرت کی کامیابی کے مقابلے میں فتوحات بھی بے معنی ہیں","k":"أخرجه الطبراني في \"المعجم الأوسط\": ۱/۳۴/۱\n(الصحيحة: ۲۷۹۰)","e":"مسلمان کو چاہیے کہ وہ اپنی آخرت سنوارنے کے لیے ہر ممکن کوشش کرے، کبھی بھی ایسا نہ ہونے پائے کہ اس کی صلاحیتیں اور لیاقتیں اس کی اخروی کامیابی کے سامنے روڑے اٹکانا شروع کر دیں۔ لیکن اس وقت دنیا میں معاملہ اس کے بالکل برعکس ہے، جس شخص میں مال و دولت، حسب و نسب، سیاست و سیادت، عہدہ و منصب اور حسن و جمال وغیرہ کی صورت میں جتنی بڑی اہلیت پائی جاتی ہے، وہ اتنا ہی آخرت سے غافل ہو جاتا ہے۔"}],[2156,"سیدنا ابو رافع رضی اللہ عنہ کہتے ہیں کہ مجھے قریشیوں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا۔ جب میں نے آپ صلی اللہ علیہ وسلم کو دیکھا تو میرے دل میں اسلام کی محبت ڈال دی گئی۔ میں نے کہا: اے اللہ کے رسول صلی اللہ علیہ وسلم! اللہ کی قسم! میں کبھی بھی ان کے پاس لوٹ کر نہیں جاؤں گے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں عہد شکنی نہیں کرتا اور نہ قاصدوں کو روکتا ہوں۔ تم لوٹ جاؤ اور اگر دل میں وہی (قبولیتِ اسلام کی چاہت) رہی، جو اب ہے تو لوٹ آنا۔“","",{"t":"عہد کی حفاظت کی عظیم مثال","k":"أخرجه أبو داود: ۱/۴۳۳-۴۳۴، والنسائي في \"السير\": ۲/۴۸/۱، وابن حبان في \"صحيحه\": ۱۶۳۰ - موارد، والحاكم: ۳/۵۹۸، وأحمد: ۶/۸\n(الصحيحة: ۷۰۲)","e":"مسلمان اور کافر، دونوں سے کیے گئے معاہدے کی پاسداری ضروری ہے، جیسا کہ آپ صلی اللہ علیہ وسلم نے مقام حدیبیہ پر مشرکین مکہ سے طے پانے والے معاہدے کا لحاظ کیا اور سیدنا ابو رافع کو واپس کر دیا۔ سنن ابی داود میں یہ وضاحت کی گئی ہے کہ سیدنا ابو رافع رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے حکم کے مطابق چلے گئے تھے، بعد میں آ کر دائرہ اسلام میں داخل ہو گئے۔ اسلام، کافروں کے ساتھ کیے گئے معاہدوں کی کس قدر پاسداری کا قائل ہے، مسلمان کی شان کا اندازہ خود لگا لینا چاہیے۔"}],[2157,"سیدنا حمزہ بن عمرو رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سفر میں روزوں کے بارے میں سوال کیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”(سفر میں روزہ رکھنے یا نہ رکھنے میں سے) جس چیز میں تیرے لیے آسانی ہو، وہ اختیار کر لے۔“","",{"t":"دوران سفر روزہ رکھنا","k":"أخرجه تمام في \"الفوائد\" ۱۶۱/۱\n(الصحيحة: ۲۸۸۴)","e":"امام البانی رحمہ اللہ لکھتے ہیں: سفر میں رمضان کے روزے رکھنے یا نہ رکھنے کے بارے میں علما و فقہا کے اقوال معروف ہیں۔ یہ بات تو یقینی ہے کہ دوران سفر روزہ ترک کرنا رخصت ہے، ہمارا خیال ہے کہ یہ بھی عمل محبوب ہے، الا یہ کہ روزے کی قضا دینا مشکل سمجھتی جاتی ہو، ایسی صورت میں روزہ رکھ لینا ہی پسندیدہ عمل ہوگا۔ واللہ اعلم۔ اس موضوع پر وسیع مطالعہ کے خواہش مندوں کو (نیل الاوطار اور اہل علم و تحقیق کی دوسری کتب کا مطالعہ کرنا چاہیے۔ (صحیحہ: ۹۳۲)"}],[2158,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”تین دعائیں مقبول ہیں، ان کی قبولیت میں کوئی شک نہیں: باپ کی دعا، مسافر کی دعا اور مظلوم کی دعا۔“","",{"t":"والدین، مسافر اور مظلوم کی دعائیں مقبول ہوتی ہیں","k":"أخرجه البخاري في \"الأدب المفرد\": ۳۲، ۴۸۱، وأبو داود: ۱۵۳۶، والترمذي: ۲/۲۵۶، وابن ماجه: ۳۸۶۲، وابن حبان: ۲۴۰۶، والطيالسي: ۲۵۱۷، وأحمد: ۲/۲۵۸، ۳۴۸، ۴۷۸، ۵۱۷، ۵۲۳، وابن ماسي في \"فوائده - آخر جزء الأنصاري\": ۹/۲، والبرزالي في \"جزء فيه أحاديث منتخبة من جزء الأنصاري\": ۱۵ - وهو الأخير، وابن عساكر في \"تاريخ دمشق\": ۹/۲۱۱/۲\n(الصحيحة: ۵۹۶)","e":"ہمیں چاہیے کہ مظلوم کی بددعا سے بچیں اور سفر کی حالت میں اپنے لیے اور اپنی اولاد کی خیر و بھلائی کے لیے دعائیں کریں۔"}],[2159,"نبی صلی اللہ علیہ وسلم نے فرمایا: ”سفر کیا کرو تندرست رہو گے اور جہاد کیا کرو بے نیاز ہو جاؤ گے۔“ یہ حدیث سیدنا ابو ہریرہ، سیدنا عبداللہ بن عمر، سیدنا عبداللہ بن عباس، سیدنا ابو سعید رضی اللہ عنہم اور زید بن اسلم سے مرسلاً مروی ہے۔","",{"t":"سفر، تندرستی کا ضامن ہے","k":"(۱) - أما حديث أبي هريرة: فأخرجه الإمام أحمد: ۲/۳۸۰، والعقيلي في \"الضعفاء\": ۲/۹۲ (۲) - وأما حديث ابن عمر: أخرجه البيهقي في \"السنن\": ۷/۱۰۲ (۳) - وأما حديث ابن عباس: فأخرجه البيهقي، وابن عدي في \"الكامل\": ۷/۵۷ (۴) - وأما حديث أبي سعيد: فأخرجه ابن عدي أيضا: ۳/۴۵۴ (۵) - وأما حديث مرسل زيد: فأخرجه ابن أبي شيبة: ۵/۳۴۹\n(الصحيحة: ۳۳۵۲)","e":"آپ صلی اللہ علیہ وسلم جس سفر کی ترغیب دلا رہے ہیں، اس میں دو چیزیں صحت کی ضامن ہوتی ہیں، ایک تو یہ ہے کہ آدمی قسم قسم کی آب و ہوا سے گزرتا ہے اور اسے مختلف قسم کے ماکولات و مشروبات کھانے پینے کا موقع ملتا ہے، اس طرح اس کے جسم کے تمام تقاضے پورے ہو جاتے ہیں۔ جہاد کی وجہ سے مجاہد کی دنیا سے رغبت ختم ہو جاتی ہے اور دوسری وجہ یہ بھی ہے کہ اسے اتنا مالِ غنیمت مل جاتا ہے کہ اسے لوگوں سے کوئی لالچ نہیں رہتا۔"}],[2160,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”تم سے پہلے کسی انسان کے لیے مالِ غنیمت حلال نہیں تھا، آسمان سے آگ نازل ہوتی اور مالِ غنیمت جلا دیتی تھی۔“ جس دن بدر کا معرکہ ہوا، لوگ غنیمتوں کے حلال ہونے سے پہلے ان کے حصول کے لیے ان پر ٹوٹ پڑے۔ اللہ تعالیٰ نے یہ آیت اتاری: ﴿اگر پہلے ہی سے اللہ کی طرف سے بات لکھی ہوئی نہ ہوتی تو جو کچھ تم نے لیا ہے اس بارے میں تمھیں کوئی بڑی سزا ہوتی۔﴾ (سورۂ انفال: ۶۸)","",{"t":"مالِ غنیمت حلال ہو گیا","k":"أخرجه الترمذي: ۳۰۸۴، وابن حبان: ۱۶۶۸، والطحاوي في \"المشكل\": ۴/۲۹۲\n(الصحيحة: ۲۱۵۵)"}],[2161,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہم سے پہلے لوگوں کے لیے غنیمتیں حلال نہیں تھیں۔ اللہ تعالیٰ نے ہماری کمزوری اور بے بسی کی بنا پر ان کو ہمارے لیے حلال کر دیا۔“","",{"t":"مالِ غنیمت حلال ہو گیا","k":"أخرجه أحمد في \"المسند\": ۲/۳۱۷، والسلمي في \"صحيفة همام\": رقم ۸۷، ومن طريقه أبو القاسم الأصبهاني في \"الحجة\": ۴۳/۲، والبيهقي: ۶/۲۹۰، وأخرجه البخاري: ۳۱۲۴ مطولا ومسلم: ۵/۱۴۵\n(الصحيحة: ۲۷۴۲)","e":"ان احادیث میں اللہ تعالیٰ کے ایک فضل کا بیان ہے، یہ خاصہ ہمیں ہماری عجز و بے بسی کی وجہ سے ملا۔"}],[2162,"عثمان بن ارقم بن ابو ارقم اپنے باپ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بدر والے دن فرمایا: ”تمھارے پاس جو مالِ غنیمت ہے، وہ رکھ دو۔“ ابو اسید ساعدی رضی اللہ عنہ نے ابن عائذ مرزبان کی تلوار رکھ دی، ارقم بن ابو ارقم نے اسے پہچان لیا اور کہا: اے اللہ کے رسول یہ مجھے دے دیں۔ آپ صلی اللہ علیہ وسلم نے اسے دے دی۔","",{"t":"تقسیم مالِ غنیمت خلیفہ و امام کے حکم سے ہو گا","k":"أخرجه الحاكم: ۳/۵۰۴، والطبراني في \"المعجم الكبير\": ۱/۲۸۵-۲۸۶/۹۰۹، \"الأوسط\": ۲/۷۱/۱/۶۱۷۳، وأبو نعيم في \"المعرفة\": ۱/۷۹/۱\n(الصحيحة: ۲۹۰۳)","e":"دشمنانِ اسلام سے سختی اور غلبے کے ذریعے چھینے ہوئے مال کو مالِ غنیمت کہتے ہیں۔ اس مال میں شرکت کرنے والے ہر مجاہد کا حصہ ہوتا ہے، سوار کو تین حصے دیے جاتے ہیں اور پیدل کو ایک، لیکن کون سی چیز کس کو دینی ہے اور کس کی درخواست پر کتنا عمل کرنا ہے، یہ حکمران کی مرضی ہے۔ یہ بات علیحدہ ہے کہ اسے شریعت کی روشنی میں مکمل عدل و انصاف کرنا ہوگا۔"}],[2163,"سیدنا برا رضی اللہ عنہ بیان کرتے ہیں کہ ایک انصاری آدمی ہتھیاروں سے لیس ہو کر نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہا: اے اللہ کے رسول! میں لڑوں یا اسلام قبول کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہیں، بلکہ اسلام قبول کر پھر جہاد کرنا۔“ وہ مسلمان ہو گیا، پھر جہاد کیا اور شہید ہو گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس نے (تھوڑا وقت) عمل کیا اور بہت زیادہ اجر و ثواب حاصل کر لیا۔“","",{"t":"ہر عمل کے لیے توحید شرط ہے عمل قلیل، لیکن اجر کثیر","k":"أخرجه البخاري: ۲۸۰۸، وأحمد: ۴/۲۹۱ و ۲۹۳، ومسلم: ۶/۴۳\n(الصحيحة: ۲۹۳۲)","e":"آپ صلی اللہ علیہ وسلم نے پہلے مشرف با اسلام ہونے کی تلقین کی، کیونکہ قبولیت اسلام کے بغیر اعمال صالحہ فائدہ مند نہیں ہوتے۔ جب کوئی کافر، اسلام قبول کرتا ہے تو اس کے سابقہ تمام گناہ معاف ہو جاتے ہیں، یہی قاعدہ اس شخص کے حق میں استعمال کیا گیا، جو چند لمحے یا چند گھڑیاں عمل کر کے جنت کا حقدار بن گیا۔"}],[2164,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”سرداری کے شروع میں ملامت ہوتی ہے، آخر میں ندامت و پشیمانی اور روزِ قیامت عذاب ہوتا ہے۔“","",{"t":"سرداری ہر اعتبار سے نقصان دہ ہے","k":"رواه الطيالسي في \"مسنده\": رقم ۲۵۲۶، وأبو العباس الأصم في \"حديثه\": ۳/۱۴۸/۱ رقم ۱۲۵\n(الصحيحة: ۱۹۸۲)","e":"سرداری، امارت، خلافت یا کسی منصب حکومت کی آرزو کرنا اور اس کے لیے کوشش کرنا ناپسندیدہ ہے، اگر کوئی یہ منصب قبول کرتا ہے، تو اس کے لیے دو شرطیں ہیں: ایک: اس منصب کی اہلیت، اور دوسری، اس منصب کی ذمہ داریوں کی ادائیگی کی استعداد و قوت اور امانت و دیانت کے ساتھ ان کو ادا کرنے کا جذبہ۔ چونکہ یہ بہت بڑی امانت ہے، اس لیے اکثر لوگ اس میں کوتاہیوں کی وجہ سے عند اللہ بھی مجرم اور عذاب آخرت کے مستحق ٹھہرتے ہیں اور لوگوں کی طعن و تشنیع کا نشانہ بھی بنتے ہیں۔"}],[2165,"سیدنا انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں کے لیے سردار ہونا ضروری ہے، (لیکن) سردار ہونا جہنم میں ہے۔“","",{"t":"سرداری ہر اعتبار سے نقصان دہ ہے","k":"أخرجه أبو الشيخ في \"طبقات الأصبهانيين\" ص ۲۵ معلقا، و وصله أبو نعيم في \"أخبار أصبهان\": ۲/۱۴۸\n(الصحيحة: ۱۴۱۷)","e":"کوئی شک نہیں کہ خلیفہ، امیر اور سردار کے بغیر زندگی نہیں گزاری جا سکتی، لیکن دیکھا گیا ہے کہ جو بھی اس منصب پر آیا، وہ نہ صرف عدل و انصاف کو برقرار نہ رکھ سکا، بلکہ انسانیت پر ظلم ڈھانے لگا، جیسا کہ اس وقت پوری دنیا کے حکمرانوں اور منصب داروں کی صورتحال ہے (الا ما شاء اللہ) ہاں اگر آدمی امانتدار اور اپنی ذمہ داریوں کو سمجھنے والا ہو تو یہ اس کے لیے عظیم منصب ثابت ہوگا، خلفائے راشدین کی مثالیں ہمارے سامنے ہیں۔"}],[2166,"سیدنا رباح بن ربیع رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک غزوہ میں تھے، آپ نے کچھ لوگوں کو ایک چیز پر ہجوم کیے دیکھا اور ایک آدمی کو بھیجا کہ (جاؤ اور) دیکھ کر آؤ کہ لوگ کس چیز پر جمع ہیں؟ اس نے واپس آ کر کہا: مقتولہ عورت پر جمع ہیں۔ آپ نے فرمایا: ”اس کو تو قتل نہیں کیا جانا چاہیے تھا۔“ اس وقت ہراول دستے کے کمانڈر خالد بن ولید تھے، آپ نے ایک آدمی کے ذریعے پیغام بھیجا کہ: ”خالد کو کہو کہ وہ عورت کو قتل کرے نہ کسی نوکر چاکر کو۔“","",{"t":"دوران قتال عورت اور نوکر کو قتل نہ کیا جائے","k":"أخرجه أبو داود: ۱/۴۱۶\n(الصحيحة: ۷۰۱)","e":"مختلف روایات سے معلوم ہوتا ہے کہ دوران قتال عورتوں، معذوروں، بوڑھوں اور بچوں کو قتل نہ کیا جائے۔ اگر ضرورت پڑ جائے تو ایسے افراد کو قتل کرنا جائز ہے، جیسا کہ سیدنا صعب بن جثامہ رضی اللہ عنہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ابواء یا ودان مقام کے پاس سے گزرے، صحابہ کی طرف سے آپ صلی اللہ علیہ وسلم سے یہ سوال کیا گیا کہ جب وہ مشرکوں پر شب خون مارتے ہیں تو بیچ میں عورتیں اور بچے بھی مار دیے جاتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: «ھم منھم» ..... ”وہ بھی ان میں سے ہی ہیں۔“ (بخاری: ۳۰۱۴) «ھم منھم» کا یہ مطلب نہیں کہ ان کو قتل کرنے کا عام حکم ہے، بلکہ اس کا مفہوم یہ ہے کہ جب ان کو قتل کیے یا روندے بغیر اصل جنگجوؤں تک رسائی حاصل کرنا ممکن نہ ہو یا اندھیرے میں امتیاز کرنا مشکل ہو تو ان کو قتل کرنا بھی جائز ہوگا۔"}],[2167,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر میں نماز فجر ادا کرتے تو سواری سے اتر کر کچھ دیر چلتے۔","",{"t":"دوران سفر نماز فجر کے بعد تھوڑا سا پیدل سفر کرنا","k":"أخرجه أبو عثمان النجيرمي: ۲/۴/۲، وأبو نعيم: ۸/۱۸۰، والبيهقي: ۵/۲۵۵، والضياء في \"الأحاديث والحكايات\": ۱۴/۱۵۱/۲، والطبراني في \"الأوسط\"\n(الصحيحة: ۲۰۷۷)","e":"انسان سواری پر سفر کرنے کے بعد یا فجر کے بعد کچھ دیر پیدل چلنے میں راحت محسوس کرتا ہے اور سواری کی وجہ سے ہونے والی تھکاوٹ بھی قدرے دور ہو جاتی ہے، اس حدیث سے پتہ چلا کہ ایسا کرنا سنت بھی ہے۔"}],[2168,"سیدنا جندب بن سفیان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کسی ایک غزوے میں تھے، جبکہ آپ کی انگلی خون آلود تھی، آپ نے فرمایا: ”تو ایک انگلی ہی ہے جو خون آلود ہوئی ہے اور اللہ کے راستے میں اس تکلیف کا سامنا کرنا پڑا ہے۔“","",{"t":"دوران جہاد زخمی ہونے والی انگلی کو آپ صلی اللہ علیہ وسلم کا خطاب","k":"أخرجه البخاري: ۲۸۰۲، ومسلم: ۵/۱۸۱، والنسائي في \"عمل اليوم والليلة\": ۶۲۰، وأبو يعلي في \"مسنده\": ۱۵۳۳، وعنه ابن حبان في \"صحيحه\": ۶۵۴۳، وكذا ابن السني في \"عمله\": ۵۰۵، والطبراني في \"المعجم الكبير\": ۲/۱۸۶/۱۷۰۸\n(الصحيحة: ۳۲۸۲)","e":"اس میں آپ صلی اللہ علیہ وسلم اپنا محاسبہ کر رہے ہیں اور اس زخم کو معمولی لیتے ہوئے اپنے آپ کو صبر دلا رہے ہیں کہ اللہ تعالیٰ کے راستے میں ایک انگلی کا زخمی ہو جانا کوئی بڑا کمال نہیں ہے، بلکہ ایسے ہوتا رہتا ہے۔"}],[2169,"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا چھوٹا جھنڈا سفید اور بڑا جھنڈا سیاہ ہوتا تھا۔","",{"t":"آپ صلی اللہ علیہ وسلم کے جھنڈوں کا رنگ","k":"أخرجه الترمذي: ۱۶۸۱، وابن ماجه: ۲/۱۸۹، والحاكم: ۲/۱۰۵، والخطيب في \"التاريخ\": ۱۴/۳۳۲\n(الصحيحة: ۲۱۰۰)","e":"ایک فرق کا اندازہ تو ترجمہ سے ہو رہا ہے، دوسرا فرق یہ بیان کیا گیا ہے کہ ”رایہ“ صاحب حرب کے پاس ہوتا ہے، وہ اس جھنڈے پر لڑائی کرتا ہے اور جنگجو اس کی طرف مائل ہوتے ہیں، جبکہ ”لواء“ امیر اور اس کی متحدہ جماعت کی علامت ہوتا ہے اور اس کو اس کے ساتھ ساتھ رکھا جاتا ہے اور تیسرا فرق یہ کہ ”لواء“ کو نیزے پر باندھ کر اس کے ساتھ لپیٹ دیا جاتا ہے، جبکہ ”رایہ“ کو نیزے کے ساتھ باندھ کر کھلا چھوڑ دیا جاتا ہے اور وہ ہوا کی وجہ سے ہلتا رہتا ہے۔"}],[2170,"سیدنا عبداللہ بن اوفی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم زوال آفتاب کے وقت دشمن سے مقابلہ کرنا پسند کرتے تھے۔","",{"t":"قتال کا بہترین وقت","k":"أخرجه أحمد: ۴/۳۵۶، وابنه عبدالله، والطبراني في \"الكبير\"، وأخرجه البخاري: ۶/۹۱، والبيهقي بلفظ: ان رسول الله صلى الله عليه وسلم في بعض ايامه التي لقي فيها انتظر حتى مالت الشمس\n(الصحيحة: ۲۱۲۶)","e":"سیدنا نعمان بیان کرتے ہیں: كَانَ إِذَا غَزَا فَلَمْ يُقَاتِلْ أَوَّلَ النَّهَارِ لَمْ يُعَجِّلْ حَتَّى تَحْضُرَ الصَّلَوَاتُ، وَتَهُبَّ الْأَرْوَاحُ، وَيَطِيبَ الْقِتَالُ ..... جب آپ صلی اللہ علیہ وسلم کسی غزوہ میں تشریف لے جاتے تو دن کے شروع میں لڑائی نہ کرتے، بلکہ ٹھہرتے حتی کہ نماز کا وقت حاضر ہو جاتا (یعنی سورج ڈھل جاتا)، ہوائیں چلنا شروع ہو جاتیں اور لڑنا خوشگوار ہو جاتا۔ (صحیحہ: ۲۸۲۶) زوال آفتاب کے بعد والے وقت میں پھرتی اور مستعدی زیادہ ہوتی ہے، جنگ اور اسلحہ کی تیزی اور جوش میں سکون آ جاتا ہے اور نماز ظہر کی ادائیگی کے فصل بعد جنگ کا آغاز ہوتا ہے، جو نیک فال اور قبولیت دعا کی علامت ہے۔ زوال کے بعد عام طور پر ٹھنڈی ہوائیں چل پڑتی ہیں اور یہ بھی ممکن ہے کہ غزوہ خندق میں ہواؤں کی وجہ سے دشمن بھاگ گیا تھا، اس لیے ان کو بھی فتح کا مظنہ سمجھا لیا گیا۔"}],[2171,"عقبہ بن مغیرہ اپنے پڑدادا مخارق سے روایت کرتے ہیں، وہ کہتے ہیں کہ میں جنگ جمل والے دن سیدنا عمار رضی اللہ عنہ کو ملا اور وہ سینگ میں پیشاب کر رہے تھے۔ میں نے کہا: اگر میں نے آپ کے ساتھ لڑنا ہے، تو آپ کے ساتھ ہو جاتا ہوں؟ انھوں نے کہا: اپنے قوم کے جھنڈے کے نیچے لڑو، کیونکہ رسول اللہ صلی اللہ علیہ وسلم آدمی کے لیے اس بات کو پسند کرتے تھے کہ وہ اپنی قوم کے جھنڈے کے نیچے لڑے۔","",{"t":"ہر کوئی اپنی قوم کے جھنڈے تلے ہو گا","k":"أخرجه أحمد: ۴/۲۶۳، وأبو يعلي في \"مسنده\": ۳/۲۰۶/۱۶۴۱\n(الصحيحة: ۳۱۱۶)","e":"لشکر اسلام مختلف اقوام پر مشتمل ہوتا تھا اور ہر قوم کا جھنڈا علیحدہ ہو کر لڑتا تھا، اس لیے آپ صلی اللہ علیہ وسلم نے یہ تعلیم دی کہ آدمی اپنی قوم کے دھڑے کے ساتھ مل کر جنگ کرے، تاکہ اس کی بہادری کے جوہر میں مزید نکھار پیدا ہو سکے۔"}],[2172,"سیدہ ام سلمہ رضی اللہ عنہا روایت کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعرات کو سفر کرنا پسند کرتے تھے۔","",{"t":"جمعرات کو سفر کا آغاز کرنا","k":"أخرجه أبو الشيخ في \"أخلاق النبي صلى الله عليه وسلم\": ۲۶۲، وابن عدي: ۱۱۴/۱، والطبراني في \"الكبير\"\n(الصحيحة: ۲۱۲۸)","e":"سیدنا کعب بن مالک رضی اللہ عنہ کہتے ہیں: نبی کریم صلی اللہ علیہ وسلم غزوہ تبوک کے موقع پر جمعرات والے دن نکلے اور آپ اسی دن کو نکلنا پسند کرتے تھے۔ اور ایک روایت میں ہے: آپ صلی اللہ علیہ وسلم سفر کے لیے کم ہی نکلتے تھے، مگر جمعرات کے دن۔ (بخاری: ۲۹۴۹، ۲۹۵۰) ہمیں بھی اس سنت کا اہتمام کرنا چاہیے، اگرچہ دوسرے دنوں میں بھی سفر کا آغاز کرنا درست ہے، جیسا کہ آپ صلی اللہ علیہ وسلم حجۃ الوداع کے موقع پر سنیچر وار کو گھر سے نکلے تھے۔"}],[2173,"عامر بن سعد بن ابو وقاص اپنے باپ سے روایت کرتے ہیں کہ جب سیدنا سعد بن معاذ رضی اللہ عنہ نے بنو قریظہ کے بارے میں یہ فیصلہ دیا کہ جن (مردوں) کے زیر ناف بال نکل آئے ہیں، انھیں قتل کر دیا جائے اور ان کے اموال اور بیوی بچوں کو (بطور قیدی) تقسیم کر دیا جائے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”(سعد) نے ان کے بارے میں آج وہ فیصلہ کیا ہے جو اللہ تعالیٰ نے سات آسمانوں کے اوپر سے کیا ہے۔“","",{"t":"بنو قریظہ کے بارے میں سیدنا سعد رضی اللہ عنہ کا فیصلہ","k":"أخرجه النسائي في \"مناقب الكبري\": ۵/۶۲-۶۳/۸۲۲۳، وابن سعد في \"الطبقات\": ۳/۴۲۶، والطحاوي في \"شرح المعاني\": ۲/۱۲۴ الهندية، والحاكم: ۲/۱۲۴، وعبد بن حميد في \"المنتخب من المسند\": ۲۵/۱-۲، ومن طريقه العسقلاني في \"تخريج المختصر\" ق ۲۳۷/۱، والبزار: ۲/۳۰۱ البحر الزخار\n(الصحيحة: ۲۷۴۵)","e":"بنو قریظہ نے غزوہ خندق کے موقع پر عہد شکنی کی تھی، آپ صلی اللہ علیہ وسلم اس غزوہ سے فارغ ہو کر انصار و مہاجرین کے جلو میں نکلے اور بنو قریظہ کا محاصرہ کر لیا، جو پچیس دنوں تک جاری رہا، آخر کار بنو قریظہ سیدنا سعد بن معاذ رضی اللہ عنہ کی ثالثی پر راضی ہو گئے، انھوں نے یہ فیصلہ دیا کہ ان کے مردوں کو قتل کر دیا جائے اور عورتوں اور بچوں کو قیدی بنا لیا جائے اور ان کے اموال تقسیم کر دیے جائیں۔"}],[2174,"ہبیرہ بن مریم کہتے ہیں کہ سیدنا حسن بن علی رضی اللہ عنہ نے لوگوں کو خطبہ دیا اور کہا: لوگو! کل ایسے آدمی (سیدنا علی رضی اللہ عنہ) نے تم کو داغِ مفارقت دیا ہے، کہ پہلے لوگ جس سے سبقت نہ لے سکے اور بعد والے لوگ جس (کے مقام) کو نہ پا سکیں گے۔ جب رسول اللہ صلی اللہ علیہ وسلم کوئی لشکر بھیجتے تو انھیں جھنڈا تھماتے تھے، وہ اس وقت تک نہ لوٹتے جب تک فتح نہ ہو جاتی، ان کی دائیں جانب جبریل ہوتے تھے اور بائیں جانب میکائیل۔ ان کی مراد ’سیدنا علی رضی اللہ عنہ‘ تھے۔ انھوں نے درہم چھوڑا ہے نہ دینار، ماسوائے سات سو درہموں کے اور وہ بھی اس طرح بچ گئے کہ وہ ایک خادم خریدنا چاہتے تھے۔","",{"t":"دوران قتال جبریل و میکائیل کا سیدنا ابو بکر اور سیدنا علی رضی اللہ عنہما کے ساتھ ہونا","k":"أخرجه ابن حبان: ۲۲۱۱، وأحمد: ۱/۱۹۹، والبزار: ۲۵۷۴- الكشف، والطبراني في \"المعجم الكبير\": ۱/۱۳۱/۱، والنسائي في \"الخصائص\": رقم ۲۵، وابن عساكر: ۱۲/۲۱۵/۱-۲\n(الصحيحة: ۲۴۹۶)"}],[2175,"سیدنا علی رضی اللہ عنہ کہتے ہیں: مجھے اور سیدنا ابو بکر رضی اللہ عنہ کو نبی کریم صلی اللہ علیہ وسلم نے بدر والے دن فرمایا: ”تم میں ایک کے ساتھ جبریل اور دوسرے کے ساتھ میکائیل ہے اور اسرافیل بھی بہت بڑا فرشتہ ہے جو جنگ میں یا جنگ کی صف میں شریک ہوتا ہے۔“","",{"t":"دوران قتال جبریل و میکائیل کا سیدنا ابو بکر اور سیدنا علی رضی اللہ عنہما کے ساتھ ہونا","k":"أخرجه ابن أبي شيبة في \"المصنف\": ۱۲/۱۶/۱۲۰۰۲، وأحمد: ۱/۱۴۷، وابن سعد في \"الطبقات\": ۳/۱۷۵-۱۷۶، والبزار: ۲/۳۱۴/۱۷۶۵، وأبو يعلي: ۱/۲۸۳، وابن أبي عاصم في \"السنة\": ۲/۵۷۴-۵۷۵، والحاكم: ۳/۶۸\n(الصحيحة: ۳۲۴۱)","e":"اس میں سیدنا ابو بکر اور سیدنا علی رضی اللہ عنہما کی فضیلت کا بیان ہے، نیز ثابت ہوا کہ فرشتے بھی میدانِ قتال میں حاضر ہوتے ہیں۔"}],[2176,"سیدنا انس رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم بدر کی طرف چلے اور لوگوں سے مشورہ کیا، سیدنا ابو بکر رضی اللہ عنہ نے ایک مشورہ دیا۔ آپ صلی اللہ علیہ وسلم نے پھر مشورہ کیا، سیدنا عمر رضی اللہ عنہ نے ایک مشورہ دیا، آپ خاموش ہو گئے۔ ایک انصاری نے کہا: (انصاریو!) نبی کریم صلی اللہ علیہ وسلم تم سے مشورہ لینا چاہتے ہیں، انھوں نے کہا: اے اللہ کے رسول! آپ ہم سے مشورہ لینا چاہتے ہیں؟ اللہ کی قسم! ہم اس طرح نہیں کہیں گے، جس طرح بنو اسرائیل نے حضرت موسیٰ علیہ السلام سے کہا تھا: ﴿(موسیٰ!) تو اور تیرا رب، تم دونوں جاؤ اور لڑو، ہم تو یہاں بیٹھے ہیں﴾ (سورۂ مائدہ: ۲۴) اللہ کی قسم! اگر آپ ”برک الغماد“ تک سواریوں کو چلاتے رہیں تو ہم آپ صلی اللہ علیہ وسلم کے ساتھ چلیں گے۔","",{"t":"غزوہ بدر کے لیے مشاورت انصار یوں کا جذبہ جہاد","k":"أخرجه النسائي في \"السنن الكبري\": ۵/۱۷۰/۸۵۸۰ و ۶/۳۳۴/۱۱۱۴۱، وأحمد: ۶/۱۰۵ و ۱۸۸ - والسياق والزيادة له -، وأبو يعلي: ۶/۴۰۷/۳۷۶۶، ۴۳۰/۳۸۰۳، ومن طريقه ابن حبان في \"صحيحه\": ۱۱/۲۳/۴۷۲۱ - المؤسسة\n(الصحيحة: ۳۳۴۰)","e":"اس سے صلاح و مشورہ کی اہمیت واضح ہوتی ہے، نیز انصار یوں کی فضیلت عیاں ہوتی ہے کہ ان میں نبی کریم صلی اللہ علیہ وسلم کی اطاعت کا جذبہ کوٹ کوٹ کر بھرا ہوا تھا۔ یمن میں ایک جگہ کا نام ”برک الغماد“ ہے۔"}],[2177,"سیدنا رفاعہ بن رافع زرقی رضی اللہ عنہ کہتے ہیں کہ حضرت جبریل علیہ السلام نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور پوچھا: تم اہل بدر کو اپنے اندر کیا شمار کرتے ہو؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”سب مسلمانوں میں افضل۔“ اس نے کہا: ایسے ہی وہ فرشتے (افضل ہیں) جو جنگ بدر میں حاضر ہوئے تھے۔","",{"t":"اہل بدر کی فضیلت","k":"أخرجه ابن أبي خيثمة في \"التاريخ\": ۲۳۰، وأخرج البخاري: ۳۹۹۳ نحوه\n(الصحيحة: ۲۵۲۸)","e":"اس میں بدر میں شریک ہونے والے مجاہدین کی فضیلت کا بیان ہے، جس سے جہاد کی اہمیت واضح ہو جاتی ہے۔"}],[2178,"سیدنا سلیمان بن صرد رضی اللہ عنہ کہتے ہیں: جب غزوہ خندق والے دن لشکروں کو بھگا دیا گیا تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”اب ہم (غزوہ خندق میں شکست سے دوچار ہونے والے مشرکین مکہ سے) لڑنے کے لیے ان کے علاقے میں گھسیں گے، وہ ہم پر چڑھائی نہیں کریں گے، اب ہم ان کی طرف پیش قدمی کریں گے۔“","",{"t":"غزوہ خندق کے بعد مشرک چڑھائی نہ کر سکے","k":"أخرجه البخاري: ۴۱۰۹، ۴۱۱۰، والطيالسي: ۱۲۸۹، وأحمد: ۴/۲۶۲، والطبراني في \"المعجم الكبير\": ۷/۱۱۵/۶۴۸۴ و ۶۴۸۵، وأبو نعيم في \"الحلية\": ۴/۳۴۵، ۷/۱۳۵، والبيهقي في \"الدلائل\": ۳/۴۵۷\n(الصحيحة: ۳۲۴۳)","e":"غزوہ خندق در حقیقت جان و مال کے نقصان کی جنگ نہیں تھی، یہ اعصاب کی جنگ تھی، اس میں کوئی خونریز معرکہ پیش نہیں آیا، لیکن پھر بھی یہ اسلامی تاریخ کی ایک فیصلہ کن جنگ تھی، چنانچہ اس کے نتیجے میں مشرکین کے حوصلے ٹوٹ گئے اور یہ واضح ہو گیا کہ عرب کی کوئی قوت مدینہ منورہ میں نشوونما پانے والی طاقت کو ختم نہیں کر سکتی، کیونکہ غزوہ احزاب میں عربوں کی جتنی بڑی طاقت فراہم ہو گئی تھی، اس سے بڑی طاقت فراہم کرنا ان کے بس کی بات نہ رہی تھی، اس لیے وہ اس واقعے کے بعد مدینہ منورہ کا رخ نہ کر سکے۔ یہ حدیث، اعلام نبوت میں سے ایک ہے، کیونکہ جیسے آپ صلی اللہ علیہ وسلم نے فرمایا، ایسے ہی ہوا۔ غزوہ خندق کے بعد نہ تو مشرکین مکہ، مدینہ منورہ کا رخ کر سکے اور نہ کسی میدان میں آپ صلی اللہ علیہ وسلم کے لشکر کا سامنا کر سکے۔ ۵ھ میں غزوہ خندق پیش آیا تھا، ۶ھ میں آپ صلی اللہ علیہ وسلم عمرہ کرنے کے لیے روانہ ہوئے، لیکن عمرہ کی ادائیگی نہ ہو سکی اور حدیبیہ کے مقام پر مشرکین مکہ سے صلح کا واقعہ پیش آیا، جو مسلمانوں کے حق میں فتح مبین کا پیغام تھا، پھر مشرک یہ معاہدہ برقرار نہ رکھ سکے اور ۸ھ میں آپ صلی اللہ علیہ وسلم نے مکہ مکرمہ فتح کر کے مشرکین مکہ کا سلسلہ ہی ختم کر دیا۔"}],[2179,"ابو جرول زہیر بن صرد جسمی کہتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے ہمیں غزوہ حنین (ہوازن) کے دن قیدی بنایا، تو آپ نے نوجوانوں اور عورتوں کو علیحدہ علیحدہ تقسیم کرنا شروع کر دیا۔ میں نے اس وقت یہ اشعار پڑھے: اے اللہ کے رسول صلی اللہ علیہ وسلم! ہم پر احسان کرو، مہربانی ہوگی۔ آپ ایسی شخصیت ہیں، جن سے ہمیں امید ہے اور (اپنی درخواست پوری ہونے کا) انتظار ہے۔ با عصمت عورتوں پر احسان کرو، جنھیں تقدیر نے پابند کر دیا ہے۔ جن کی شیرازہ بندی زمانے میں بکھر چکی ہے۔ زمانے نے ہمیں غمگین ہو کر چلانے پر مجبور کر دیا ہے۔ ہمارے دلوں پر سختی و مصیبت چھائی ہوئی ہے۔ اگر ان پر احسان نہیں کریں گے تو وہ بکھر جائیں گی۔ اے وہ ہستی جو کٹھن مراحل میں بردباری میں راج ترین ہوتی ہے۔ ان عورتوں پر رحم کرو کہ جن کا تم دودھ پیتے تھے۔ وہ تمھیں اس وقت مزین کر رہی تھیں، جب کچھ چیزیں اختیار کی جاتی ہیں اور کچھ کو ترک کر دیا جاتا ہے۔ تم ان کو اس طرح نہ کر دو کہ جن کا شیرازہ بکھر چکا ہوتا ہے۔ تم ہم پر احسان کرنے میں ہم سے سبقت لے جاؤ، ہم تو ایک ہی قوم ہیں۔ جن نعمتوں کی ناشکری کی جاتی ہے، ہم ان کا شکر یہ ادا کریں گے۔ اور ہم آج کے بعد آپ کے احسان مند ہوں گے۔ ان کو معاف کر دو کہ جن کا تم دودھ پیتے تھے۔ یعنی اپنی ماؤں کو، بیشک اس معافی کو شہرت ملے گی۔ اے وہ بہترین شخصیت کہ سیاہ و سرخ گھوڑوں (کے سوار حفاظت کے لیے) جن کو گھیر لیتے ہیں۔ اس وقت جب (جنگ میں) جوش و خروش اور چنگاریاں اٹھ رہی ہوتی ہیں۔ تم سے معافی (کے لباس) کی امید رکھتے ہیں، ہم وہ پہنیں گے۔ اے مخلوق کے ہادی! جب تم معاف کرو گے اور بازی مار جاؤ گے۔ تم معاف کر دو، اللہ تمھارے لیے روز قیامت وہ امور معاف کر دے جن سے ڈرتے ہو، جب کامیابی تمھارے ہمرکاب ہوگی۔ جب آپ صلی اللہ علیہ وسلم نے یہ اشعار سنے تو فرمایا: ”جو میرا اور عبد المطلب کا حصہ ہے، وہ تم لوگوں کا ہے۔“ قریشیوں نے کہا: جو ہمارے حصے میں آیا، وہ بھی اللہ تعالیٰ اور اس کے رسول کے لیے ہے۔ اور انصاریوں نے کہا: جو کچھ ہمارے حصے میں آیا وہ بھی اللہ تعالیٰ اور رسول اللہ صلی اللہ علیہ وسلم کا ہے۔","",{"t":"وفد بنو ہوازن کی آمد اور آپ صلی اللہ علیہ وسلم کا ان پر احسان","k":"أخرجه الطبراني في \"الكبير\": ۵/۲۶۹/۵۳۰۳، و \"الصغير\": ۱/۲۳۶، و \"الاوسط\": ۴۶۳۰\n(الصحيحة: ۳۲۵۲)","e":"غزوہ طائف، جو شوال ۸ھ میں پیش آیا، سے فارغ ہو کر آپ صلی اللہ علیہ وسلم نے جعرانہ مقام پر پڑاؤ ڈالا اور دس دن سے زیادہ ٹھہرے رہے اور مال غنیمت تقسیم نہ کیا، آپ صلی اللہ علیہ وسلم کو یہ انتظار تھا کہ ہوازن توبہ کر کے آ جائیں اور اپنے مال اور قیدی واپس لے جائیں گے، لیکن جب کوئی نہ آیا تو آپ صلی اللہ علیہ وسلم نے مال غنیمت تقسیم کر دیا۔ تقسیم کے بعد ہوازن کا وفد اپنے رئیس زہیر بن صرد سمیت پہنچ گیا اور عرض پرداز ہوا، تفصیل درج بالا حدیث میں گزر چکی ہے، پھر آپ صلی اللہ علیہ وسلم نے انھیں نماز ظہر کے بعد اپنے اسلام کا اظہار کرنے اور اپنے مال اور قیدی واپس لینے کی ترکیب بتائی، جس میں وہ کامیاب ہو گئے۔"}],[2180,"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہر آدمی کے سر میں قدر و منزلت، جو فرشتے کے ہاتھ میں ہوتی ہے، پائی جاتی ہے۔ جب بندہ عاجزی اختیار کرتا ہے تو فرشتے سے کہا جاتا ہے کہ اس کی قدر و منزلت کو بلند کر دے اور جب وہ تکبر کرتا ہے تو فرشتے کو کہا جاتا ہے کہ اس کی قدر و منزلت کو پست کر دے۔“","",{"t":"عاجزی، رفعت کا اور تکبر، ذلت کا سبب کیسے بنتے ہیں؟","k":"أخرجه الطبراني في \"المعجم الكبير\": ۳/۱۸۲/۱، والحاكم: ۲/۵۹۱\n(الصحيحة: ۵۳۸)","e":"اللہ تعالیٰ ہی ہے جو عزتوں سے نوازتا ہے اور ذلتوں سے دو چار کرتا ہے، بہر حال عجز و انکساری اس کو پسند ہے اور غرور و تکبر اس کو سخت ناپسند ہے۔ اس حدیث میں اس چیز کا بیان ہے کہ آدمی کیسے عزت پاتا ہے اور کیسے ذلیل ہو جاتا ہے۔ ہمیں چاہیے کہ اپنے مزاج کو شریعت کی روشنی میں تبدیل کریں۔"}],[2181,"سیدنا عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”جب کوئی آدمی زخمی ہو جاتا ہے اور پھر وہ (زیادتی کرنے والے کو) معاف کر دیتا ہے تو اللہ تعالیٰ اس کی معافی کے بقدر (اس کے گناہوں کو) مٹا دیتا ہے۔“","",{"t":"معافی کا اجر و ثواب","k":"أخرجه أحمد: ۵/۳۱۶، ۳۲۹، ۳۳۰\n(الصحيحة: ۲۲۷۳)","e":"مقدار کا علم اللہ تعالیٰ کو ہے کہ کتنے زخم کی وجہ سے کتنے گناہ معاف ہوتے ہیں۔"}],[2182,"سیدنا ابو کبشہ انماری رضی اللہ عنہ ایک آدمی کے پاس آئے اور کہا: مجھے جفتی کے لیے گھوڑا عاریہ دو، میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ”جس نے جفتی کے لیے کسی مسلمان کو عاریہ گھوڑا دیا تو اسے اللہ کے راستے میں دیے جانے والے ستر گھوڑوں کے ثواب جتنا اجر ملے گا۔ اگر اس جفتی کی وجہ سے اولاد نہ ہو تو اللہ تعالیٰ کے راستے میں دیے جانے والے ایک گھوڑے کے ثواب کے برابر اجر ملے گا۔“","",{"t":"جفتی کے لیے گھوڑا دینے کا اجر و ثواب","k":"أخرجه ابن حبان: ۱۶۳۷- الموارد، وأحمد: ۴/۲۳۱، وأبو اسحاق الحربي في \"غريب الحديث\": ۵/۹/۱، والطبراني في \"المعجم الكبير\": ۲۲/۳۴۱/۸۵۳\n(الصحيحة: ۲۸۹۸)"}],[2183,"سیدنا فضالہ بن عبید رضی اللہ عنہ کہتے ہیں: جو آدمی، برے شگون کی وجہ سے (کسی کام سے) رک جاتا ہے، وہ شرک سے آلودہ ہو جاتا ہے۔","",{"t":"بد فالی کی بنا پر کسی کام کے ارادے کو ترک نہیں کرنا چاہیے","k":"رواه ابن وهب في \"الجامع\" ص ۱۱۰، واحمد: ۲/۲۲۰، والطبراني\n(الصحيحة: ۱۰۶۵)","e":"دورِ جاہلیت میں بعض اسباب کے ذریعے سے نیک شگونی یا بدشگونی لینا عام تھا، مثلاً سفر کا ارادہ کرنے والا کسی پرندے کو اڑاتا، اگر وہ دائیں جانب اڑ جاتا، تو وہ اسے سفر خیر کی علامت سمجھتے ہوئے سفر شروع کر دیتا، اور اگر وہ پرندہ بائیں جانب اڑ جاتا تو وہ اسے منحوس سفر کی علامت سمجھ کر اپنا ارادہ ترک کر دیتا۔ کئی اور علامتیں بھی مقرر تھیں۔ یہ سب امور ممنوع اور حرام ہیں۔ محض کسی بات کے اتفاقیہ طور پر صحیح نکل آنے سے ان تمام خرافات کا جواز ثابت نہیں ہوگا۔ جلبِ منفعت یا دفع مضرت میں ان چیزوں کی کوئی تاثیر نہیں ہے۔ یہ سب ظن و تخمین اور اٹکل پچو ہیں، جن پر اعتبار اور اعتماد کرنا جہالت، گمراہی اور توہم پرستی ہے۔ اس لیے انسان کو چاہیے کہ وہ جس کام کو سر انجام دینے کا عزم کر لے، اللہ تعالیٰ پر توکل کر کے اس کو گزرے اور بدفالیوں کو اپنے ذہن میں جگہ نہ دے۔ لیکن شریعت نے اچھی بات سن کر اچھا شگون لینے کو جائز قرار دیا ہے، جس کی بنا پر انسان اللہ تعالیٰ سے حسن ظن قائم کر لیتا ہے، جو ایک مستحسن امر ہے، جیسا کہ سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «لَا عَدْوَى وَلَا طِيَرَةَ وَيُعْجِبُنِي الْفَأْلُ» ..... ”نہ کوئی بیماری متعدی ہے اور نہ کوئی بدشگونی (کی حقیقت ہے)، لیکن مجھے ”فال“ اچھی لگتی ہے۔“ صحابہ نے پوچھا: ”فال“ کیا ہوتی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: «كَلِمَةٌ طَيِّبَةٌ» ..... ”اچھی بات (کا سننا اور اس سے خیر کی امید وابستہ کر لینا)۔“ (بخاری، مسلم)"}],[2184,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے رات کو ہم پر تیر پھینکا، وہ ہم میں سے نہیں۔“","",{"t":"رات کو مسلمانوں پر تیر پھینکنے والے کی مذمت","k":"روي عن ابي هريرة و عن ابن عباس (۱) أما حديث ابي هريرة رضي الله عنه: فأخرجه أحمد: ۲/۳۲۱، والبخاري في \"الأدب المفرد\": ۱۲۷۹، وابن حبان: ۱۸۵۷ (۲) وأما حديث ابن عباس فأخرجه والطبراني: ۳/۱۲۶/۲\n(الصحيحة: ۲۳۳۹)","e":"دن کو بھی ایسا کرنا منع ہے، چونکہ رات کو تیر اور تیر پھینکنے والے کا پتہ ہی نہیں چلتا کہ دفاع کیا جا سکے اور نقصان بھی زیادہ ہو سکتا ہے اور مسلمانوں کے سکون میں خلل بھی آ سکتا ہے، اس لیے حدیث میں رات کا خاص طور پر ذکر کیا گیا ہے۔"}],[2185,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مدد، صبر کے ساتھ ہوتی ہے، کشادگی، رنج و غم کے ساتھ ہوتی ہے اور بلاشبہ تنگی کے ساتھ آسانی ہوتی ہے اور بیشک تنگی کے ساتھ آسانی ہوتی ہے۔“","",{"t":"اللہ کی مدد کی بنیاد صبر پر اور آسانی کی بنیاد مشکل پر ہے","k":"أخرجه الخطيب في \"التاريخ\": ۱۰/۲۸۷، والديلمي: ۴/۱۱۱، ۱۱۲\n(الصحيحة: ۲۳۸۲)","e":"نبی کریم صلی اللہ علیہ وسلم کے تقریباً تئیس سالہ دورِ نبوت میں سے پہلے تیرہ سال انتہائی کٹھن اور مشکل تھے، لیکن ان مشکلات اور تکلیفوں میں کیے گئے صبر کا نتیجہ دس سالہ مدنی دور کی صورت میں نکلا۔ یہی قانون قدرت ہے کہ ہر آسانی کے راستے میں مشکل اور ہر خوشی کے راستے میں غمی ہے۔"}],[2186,"یحییٰ بن اسحاق بن عبداللہ بن ابو طلحہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب سیدنا علی رضی اللہ عنہ کو بھیجا تو ان کے پیچھے ایک اور آدمی کو بھیجا اور اسے فرمایا: ”اس کے پیچھے چلتا رہ اور اس کے پیچھے ہی رہنا ہے (بلکہ) تو اس کا تعاقب کر، ان کو پکڑ لے اور کہہ کہ رسول اللہ صلی اللہ علیہ وسلم فرما رہے ہیں: ”ٹھہر جاؤ، یہاں تک میں پہنچ جاؤں۔“ وہ ٹھہر گئے، حتی کہ رسول اللہ صلی اللہ علیہ وسلم آئے اور فرمایا: ”اس وقت تک کسی قوم سے نہیں لڑنا، جب تک (اسلام کی) دعوت نہ پہنچا دو۔“","",{"t":"قتال سے پہلے دعوتِ اسلام دینا ضروری ہے","k":"أخرجه عبد الرزاق في \"المصنف\": ۵/۲۱۷/۹۴۲۴\n(الصحيحة: ۲۶۴۱)","e":"اس حدیث مبارکہ میں بڑے اہم مسئلے کی طرف توجہ دلائی گئی ہے کہ قتال سے پہلے کافروں کو اسلام کی دعوت دی جائے، اگر وہ یہ دعوت قبول کر لیں تو بہتر، وگرنہ ان پر جزیہ لاگو کر دیا جائے گا، اگر وہ جزیہ دینے سے بھی انکار کر دیں، تو ان سے اعلان جنگ ہوگا اور وہ قتال کے مستحق ٹھہریں گے۔ نبی کریم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابہ کا یہی طرز قتال تھا۔ لیکن صحیح بخاری اور صحیح مسلم کی روایت سے معلوم ہوتا کہ نبی کریم صلی اللہ علیہ وسلم نے بنو مصطلق پر شبخون مارا، جبکہ وہ غافل تھے۔ اس کا جواب یہ ہے کہ اس روایت سے معلوم نہیں ہوتا کہ آپ صلی اللہ علیہ وسلم کی دعوت ان تک نہیں پہنچی تھی۔ آپ صلی اللہ علیہ وسلم کی دعوت تو فارس و روم کے بادشاہوں تک پہنچ گئی تھی۔ یہ عصر حاضر کے بعض مؤلفوں کی کم عقلی ہے، جو اس حدیث کے بارے میں یہ کہتے ہیں کہ یہ شرعی قواعد کے مخالف ہے، حالانکہ یہ تو ضروری نہیں ہے کہ قتال سے متصل پہلے کافروں کو تبلیغ کی جائے۔ جب اسی قسم کا سوال حسن بصری سے کیا گیا تو انھوں نے کہا: کیا ان کو قتال سے پہلے دعوت دی جائے گی؟ حقیقت یہ ہے کہ حضرت محمد صلی اللہ علیہ وسلم کی بعثت کے بعد ہر ایک کافر کو دعوت اسلام پہنچ چکی ہے۔ اسے ابن ابی شیبہ (۱۲/۳۷۵) اور سعید بن منصور (۳/۲۰۷/۲۳۸۲) نے روایت کیا۔ میں نے (صحیح ابی دوا: ۲۳۶۷) میں اس موضوع پر دلالت کرنے والی بعض روایات کی تخریج پیش کر کے اس کا رد کیا ہے۔ (صحیحہ: ۲۶۴۱) جمہور علما و فقہا کی یہ رائے ہے کہ اگر ان کافروں کو سرے سے اسلام کی دعوت نہ پہنچی ہو تو ان کو دعوت دینا واجب ہے، بصورتِ دیگر مستحب ہوگی۔"}],[2187,"سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم ہجرت کر کے (مدینہ) چلے گئے تو آپ صلی اللہ علیہ وسلم کی بیٹی سیدہ زینب رضی اللہ عنہا نے اپنے خاوند ابو العاص بن ربیع سے رسول اللہ صلی اللہ علیہ وسلم کے پاس جانے کی اجازت طلب کی، اس نے اجازت دے دی۔ وہ آپ صلی اللہ علیہ وسلم کے پاس پہنچ گئیں، پھر ابو العاص بھی مدینہ پہنچ گیا اور سیدہ زینب کی طرف پیغام بھیجا کہ اپنے باپ سے میرے لیے امان حاصل کرو۔ میں نکلی اور اپنے حجرے سے جھانکا، تو دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز پڑھا رہے تھے۔ میں نے کہا: لوگو! میں زینب بنت رسول اللہ صلی اللہ علیہ وسلم ہوں، میں نے ابو العاص کو پناہ دے دی ہے۔ جب رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو فرمایا: ”لوگو! مجھے اس بات کا پتہ نہیں تھا، حتی کہ تم نے خود سن لی۔ آگاہ ہو جاؤ! ادنیٰ (اور کم مرتبہ) مسلمان بھی کسی کو مسلمانوں پر پناہ دے سکتا ہے۔“","",{"t":"ہر مسلمان پناہ دے سکتا ہے","k":"أخرجه الطبراني في \"الأوسط\": ۲/۲۹۶/۲، ۴۹۵۸، وفي \"الكبير\": ۲۳/۴۲۵/۱۰۴۷\n(الصحيحة: ۲۸۱۹)","e":"اگر چہ اعمال کی وجہ سے مومنوں اور مسلمانوں کے ایمان میں تفاوت پایا جاتا ہے، لیکن بحیثیتِ اسلام تمام مسلمانوں میں یکسانیت پائی جاتی ہے۔ مردو زن، ادنی و اعلی اور امیر و غریب میں کوئی فرق نہیں ہے، اس لیے جو مسلمان کسی کافر کو پناہ دے دے گا، دوسرے مسلمانوں پر فرض ہو گا کہ وہ اس پناہ کا لحاظ کرتے ہوئے کافر کے حقوق کا خیال رکھیں۔"}],[2188,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ”جد بن قیس! کیا تجھے بنو الاصفر سے تلوار کے ساتھ مقابلہ کرنے کی رغبت ہے؟“ جد نے کہا: اے اللہ کے رسول! آپ مجھے (اپنے ساتھ نہ جانے کی) اجازت دے دیں، کیونکہ میں عورتوں سے محبت کرتا ہوں اور مجھے اندیشہ ہے کہ بنو الاصفر کی بیٹیوں کو دیکھ کر فتنے میں نہ پڑ جاؤں گا؟ رسول اللہ صلی اللہ علیہ وسلم نے اس سے اعراض کرتے ہوئے اسے فرمایا: ”میں نے تجھے اجازت دے دی ہے۔“ اس وقت اللہ تعالیٰ نے یہ آیت نازل کی: اور ان میں سے کوئی تو کہتا ہے: مجھے اجازت دیجئے، مجھے فتنے میں نہ ڈالیے۔ آگاہ رہو! وہ تو فتنے میں پڑ چکے ہیں ﴾ (سورہ توبہ: ۴۹)","",{"t":"غزوہ تبوک کے موقع پر عذرخواہوں کا راز کھل گیا","k":"أخرجه ابن أبي حاتم في \"التفسير\": ۴/۵۱/۱\n(الصحيحة: ۲۹۸۸)","e":"جلاد کے دو معانی ہیں: (۱) یہ جَلد کی جمع ہے، جس کے معانی ”باہمت، صابر اور جری“ کے ہیں۔ (۲) یہ جَالَدَ یُجَالِد باب سے مُجالدہ کی طرح مصدر ہے، جس کے معانی ”تلوار سے مقابلہ کرنے اور شمشیر زنی کرنے“ کے ہیں۔ بنو الاصفر: ایشائے کوچک اور قسطنطنیہ وغیرہ میں رہنے والے رومی باشندوں کا لقب بنو الاصفر ہے۔ اس حدیث میں غزوہ تبوک کی طرف اشارہ کیا گیا ہے، جو رجب ۹ھ میں پیش آیا۔ اس غزوے میں آپ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابہ کے خلاف فیصلہ کن جنگ کی ضرورت محسوس کرنے والے رومیوں سے مقابلہ کرنا تھا، یہ سخت گرمی کا زمانہ تھا، لمبا سفر تھا، لوگ تنگی اور قحط سے دوچار تھے اور پھل پک چکے تھے اور سائے خوشگوار لگ رہے تھے۔ بہر حال رسول اللہ صلی اللہ علیہ وسلم نے اہل ثروت صحابہ کو تنگ دستوں کی تیاری کی ترغیب دلائی اور ان سے جو کچھ بن سکا، وہ لے آئے۔ اُدھر منافقین اور بدوی بناوٹی عذر لے لے کر آئے اور نبی کریم صلی اللہ علیہ وسلم سے اس غزوے میں عدم حضوری کی اجازت چاہی۔ آپ صلی اللہ علیہ وسلم نے اجازت دے دی۔ ان کے علاوہ بعض مسلمان محض سستی کی وجہ سے پیچھے رہ گئے۔ اس حدیث میں اسی قسم کے ایک عذر خواہ کا ذکر ہے، جو بنو الاصفر کی لڑکیوں کا بہانہ پیش کر کے دراصل اس غزوے میں شمولیت اختیار کرنے سے کترا رہا تھا، جب آپ صلی اللہ علیہ وسلم نے اسے اجازت دے دی تو بعد میں نازل ہونے والی آیت سے پتہ چلا کہ اس کا عذر درست نہیں تھا۔"}],[2189,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جبریل علیہ السلام میرے پاس آئے اور کہا: اے محمد صلی اللہ علیہ وسلم! جیسے چاہو زندگی گزارو (بالآخر) مرنا تو ہے، جس کو چاہو اپنا محبوب بناؤ (بالآخر) جدا تو ہونا ہے، اپنی چاہت کے مطابق عمل کرو (بالآخر) اس کا بدلہ تو ملنا ہے۔ (اتنا ضرور جان لو کہ مؤمن کا شرف رات کی نماز میں اور) اس کی عزت لوگوں سے بے پرواہ ہو جانے میں ہے۔“ یہ حدیث سیدنا سہل بن سعد، سیدنا جابر بن عبداللہ اور سیدنا علی بن ابو طالب رضی اللہ عنہم سے مروی ہے۔","",{"t":"بالآخر دنیا سے رخصت اور ہر دوست کو الوداع کہنا پڑے گا","k":"۱ - أما حديث سهل؛ فأخرجه الطبراني في \"الأوسط\": ۱/۶۱/۲ - من الجمع بينه وبين \"الصغير\"، والسهمي في \"تاريخ جرجان\": ۶۲، وأبو نعيم في \"الحلية\": ۳/۲۵۳، والحاكم: ۴/۳۲۴-۳۲۵، والبيهقي في \"شعب الايمان\": ۷/۳۴۹/۱۰۵۴۱-۱۰۵۴۲ - لبنان ۲ - وأما حديث جابر؛ فأخرجه الطيالسي في \"مسنده\": ۱۷۵۵، وعنه البيهقي في \"شعب الايمان\": ۱۰۵۴۰ ۳ - وأما حديث علي؛ فأخرجه أبو نعيم في \"الحلية\": ۳/۲۰۲\n(الصحيحة: ۸۳۱)","e":"اس فرمان نبوی صلی اللہ علیہ وسلم میں یہ فکر دلائی گئی ہے کہ بندہ جیسے چاہے اپنی چاہتوں اور امنگوں کو پورا کرتا رہے، بالآخر اس نے اس دنیائے فانی سے کوچ کر جانا ہے اور جس سے چاہے، دوستی کی پینگیں بڑھاتا رہے، ایک روز ایسا بھی آئے گا کہ سب کو داغ مفارقت دینا پڑے گا۔ اس میں کوئی شک نہیں ہے کہ ہر مسلم اس حقیقت کا دعویدار ہے کہ اچھے اعمال کا بدلہ اچھا اور برے اعمال کا بدلہ برا ملے گا، لیکن عملی طور پر مسلمانوں کی اکثریت غفلت میں مبتلا ہو جاتی ہے۔"}],[2190,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جبریل میرے پاس آئے اور کہا: اے محمد! جیسے چاہو زندگی گزارو (بالآخر) مرنا تو ہے، جس کو چاہو اپنا محبوب بناؤ (بالآخر) جدا تو ہونا ہے، اپنی چاہت کے مطابق عمل کرو (بالآخر) اس کا بدلہ تو ملنا ہے۔ (اتنا ضرور) جان لو کہ مؤمن کا شرف رات کی نماز میں اور اس کی عزت لوگوں سے بے پرواہ ہو جانے میں ہے۔“ یہ حدیث سیدنا سہل بن سعد، سیدنا جابر بن عبداللہ اور سیدنا علی بن ابو طالب رضی اللہ عنہم سے مروی ہے۔","",{"t":"مومن کا شرف تہجد میں اور اس کی عزت لوگوں سے بے نیاز ہونے میں ہے","k":"۱ - أما حديث سهل؛ فأخرجه الطبراني في \"الأوسط\": ۱/۶۱/۲ - من الجمع بينه وبين \"الصغير\"، والسهمي في \"تاريخ جرجان\": ۶۲، وأبو نعيم في \"الحلية\": ۳/۲۵۳، والحاكم: ۴/۳۲۴-۳۲۵، والبيهقي في \"شعب الايمان\": ۷/۳۴۹/۱۰۵۴۱-۱۰۵۴۲ - لبنان ۲ - وأما حديث جابر؛ فأخرجه الطيالسي في \"مسنده\": ۱۷۵۵، وعنه البيهقي في \"شعب الايمان\": ۱۰۵۴۰ ۳ - وأما حديث علي؛ فأخرجه أبو نعيم في \"الحلية\": ۳/۲۰۲\n(الصحيحة: ۸۳۱)","e":"حدیث مبارکہ کے دوسرے حصے میں دو اعمال کی رغبت دلائی گئی ہے کہ مومن کو چاہئے کہ وہ رات کو قیام کیا کرے۔ ارشاد باری تعالیٰ ہے: ﴿إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ .... كَانُوا قَلِيلًا مِّنَ اللَّيْلِ مَا يَهْجَعُونَ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ﴾ (سورہ ذاریات: ۱۷) ”بیشک پرہیز گار لوگ باغات اور چشموں میں ہوں گے۔ ...... (ان کی صفات یہ ہیں کہ) وہ رات کو کم سوتے ہیں اور سحریوں کے وقت بخشش طلب کرتے ہیں۔“ ارشادِ نبوی ہے: ”لوگو! سلام کو عام کرو، (لوگوں کو) کھانا کھلاؤ، جب لوگ رات کو سو رہے ہوں تو نماز (تہجد) پڑھو، سلامتی کے ساتھ تم جنت میں داخل ہو جاؤ گے۔“ (ترمذی) سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب ایک تہائی رات باقی رہ جاتی ہے تو اللہ تعالیٰ آسمانِ دنیا پر نازل ہو کر کہتے ہیں: کوئی ہے جو مجھے پکارے، تاکہ میں اس کی دعا قبول کروں۔ کوئی ہے جو مجھ سے مانگے، تاکہ میں اس کو عطا کر دوں۔ کوئی ہے جو مجھ سے بخشش طلب کرے، تا کہ میں اس کو بخش دوں۔ (بخاری، مسلم) نیز یہ ترغیب دلائی گئی ہے کہ مومن کا وقار اور احترام و اکرام اس میں ہے کہ وہ اللہ تعالیٰ پر بھروسہ رکھے اور لوگوں کے مال و دولت پر نگاہ رکھنا ترک کر دے، اللہ تعالیٰ کے ہاں بندے کی عزت کا راز اسی میں ہے کہ وہ متقی اور پرہیز گار ہو اور معاشرے میں عزت و وقار اس میں ہے کہ آدمی میں لالچ اور حرص جیسی کمینی صفات نہ ہوں۔"}],[2191,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے میرے صحابہ کیا تم جانتے ہو کہ مفلس کون ہے،؟“ صحابہ نے کہا: ہم میں مفلس وہ شخص ہے جس کے پاس نہ درہم ہو اور نہ ہی کوئی اور سامان ہو۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”(نہیں، بلکہ) میری امت میں سے مفلس وہ شخص ہے جو قیامت والے دن نماز، روزے، اور زکوۃ کے ساتھ آئے گا (لیکن اس کے ساتھ ساتھ) وہ اس حال میں آئے گا کسی کو گالی دی ہو گی، کسی پر بہتان تراشی کی ہوگی، کسی کا مال کھایا ہوگا، کسی کا خون بہایا ہو گا اور کسی کو مارا پیٹا ہو گا۔ پس ان (تمام مظلومین) کو اس کی نیکیاں دے دی جائیں گی (تاکہ ان پر کئے گئے ظلم کی تلافی ہو جائے)۔ لیکن اگر اس کی نیکیاں ختم ہو گئیں قبل اس کے کہ اس کے ذمے دوسروں کے حقوق باقی ہوں، تو ان کے گناہ لے کر اس پر ڈال دیے جائیں گے، پھر اسے جہنم میں پھینک دیا جائے گا۔","",{"t":"مفلس کون ہے؟","k":"أخرجه مسلم: ۸/۱۸، والترمذي: ۳/۲۹۱-۲۹۲، وابن حبان: ۴۳۹۴، ۷۳۱۵، وأحمد: ۲/۳۰۳، ۳۳۴، ۳۷۲، والبيهقي في \"الشعب\": ۱/۳۰۳/۳۴۴\n(الصحيحة: ۸۴۷)","e":"دیکھئے کہ حقوق العباد میں کی گئی کمی، حقوق اللہ کی ادائیگی پر ملنے والے اجر و ثواب کو لے ڈوبے گی۔ اس حدیث کا مطلب یہ ہوا کہ مسلمان کو چاہیے کہ جہاں وہ اپنے خالق کے حقوق کی پاسداری کا اہتمام کرتا ہے، اسی طرح اسے چاہیے کہ اس کی مخلوق کے حقوق ادا کرنے میں کسی قسم کی سستی و کاہلی سے کام نہ لے۔ بعض لوگوں کا خیال ہے کہ حقوق العباد کی ادائیگی زیادہ ضروری ہے، کیونکہ اللہ تعالیٰ تو اپنے حقوق معاف بھی کر سکتا ہے۔ یہ سوچ شریعت سے دوری کی علامت ہے، اگر معاملہ اللہ تعالیٰ کی بخشش کا ہے تو وہ بندوں کے حق میں کیے گئے گناہوں کو بھی معاف کروا سکتا ہے۔ اس حدیث سے حقوق العباد کی اہمیت کا اندازہ ہوتا ہے۔"}],[2192,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تک میں تمھیں چھوڑے رکھوں (یعنی کوئی جدید حکم نہ دوں) تم بھی مجھے چھوڑے رکھو (یعنی نئے نئے امور کے بارے میں دریافت نہ کرو)۔ ہاں جب میں تمھیں کوئی حکم دے دوں تو اسے اپنا لو، (یاد رکھو کہ) تم سے پہلے والی امتیں انبیا سے زیادہ سوال کرنے اور ان پر اختلاف کرنے کی وجہ سے ہلاک ہو گئیں۔“","",{"t":"کثرت سوال باعث ہلاکت ہے","k":"أخرجه الترمذي: ۳/۳۷۹، وابن ماجه: ۱/۴-۵، وأحمد: ۲/۴۹۵، وقد اخرجه البخاري: ۹/۷۷، ومسلم: ۴/۱۰۲\n(الصحيحة: ۸۵۰)","e":"ارشاد باری تعالیٰ ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾ (سورہ مائدہ: ۱۰۱) ...... ”اے ایمان والو! ایسے سوال مت پوچھو کہ اگر تم پر ان کو ظاہر کر دیا جائے تو تمھیں نا گوار لگیں۔“ نبی کریم صلی اللہ علیہ وسلم کے عہدِ مبارک میں فضول اور لا یعنی قسم کے سوالات کرنا ممنوع تھا، جیسے حضرت موسیٰ علیہ السلام نے جب اپنی قوم کو اللہ تعالیٰ کے لیے گائے ذبح کرنے کا حکم دیا تو انھوں نے پہلے تو اس حکم کو سنجیدہ نہ لیا، پھر اس کی صفات کے بارے میں پوچھتے پوچھتے اپنے حق میں تنگی کرتے رہے۔ اسی طرح جب آپ صلی اللہ علیہ وسلم نے فرمایا کہ اللہ تعالیٰ نے تم پر حج فرض کیا ہے۔ ایک شخص نے سوال کیا کہ کیا ہر سال فرض ہے؟ آپ صلی اللہ علیہ وسلم خاموش رہے، اس نے یہ سوال تین دو ہرایا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر میں جواب میں ”ہاں،“ کہہ دوں تو حج ہر سال فرض ہو جائے گا اور اگر ایسا ہو گیا تو تمہارے لیے ہر سال حج کرنا ناممکن ہو گا۔“ (مسلم) چونکہ حلت و حرمت کا تعلق صرف آپ صلی اللہ علیہ وسلم کے دور سے تھا، اب حلال و حرام کی تعین ہو چکی ہے، کسی کے سوال کرنے یا نہ کرنے سے کوئی فرق نہیں پڑتا، لیکن آپ صلی اللہ علیہ وسلم کی شریعت کے تمام احکام پر عمل کرنا ہم پر فرض ہے، جو ہم نے حسب استطاعت ادا کرنا ہے۔ آجکل لوگوں نے اپنی کم عقلی و کم فہمی کی بنا پر جدید طرز کے سوالات اٹھانا شروع کر دیے ہیں، مثلا عذاب قبر کی کیفیت کیا ہے؟ قبر کی مٹی میں مردے کا جسم گل سڑ جاتا ہے تو پھر عذاب کیسے ہوتا ہے؟ صرف تین نمازوں میں جہری قرأت کرنے کی کیا حکمت ہے؟ اس قسم کے سوالات بھی انتہائی فضول، لا یعنی اور راہ راست سے دور کرنے والے ہیں۔ ہمیں چاہیے کہ اللہ تعالیٰ اور رسول اللہ صلی اللہ علیہ وسلم نے جو کچھ فرما دیا، وہ ہماری عقل کے مطابق ممکن ہو یا محال، اسے من و عن تسلیم کر کے اس پر عمل کرنا یا اس کے مطابق اعتقاد بنانا ہمارا فرض ہے۔"}],[2193,"ابن طاؤس اپنے باپ سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عبادہ بن صامت رضی اللہ عنہ کو صدقات (کی وصولی) پر عامل مقرر کیا اور اسے فرمایا: ”ابو الولید! اللہ تعالیٰ سے ڈرتے رہنا، (کہیں ایسا نہ ہو کہ) تو روزِ قیامت اپنی گردن پر بلبلاتا ہوا اونٹ، ڈکارتی ہوئی گائے یا ممیاتی ہوئی بکری اٹھا کر لے آئے (جو تو نے خیانت کر لی ہو)۔“","",{"t":"خیانت کیے ہوئے اونٹ، گائے اور بکری کی وجہ سے میدانِ حشر میں رسوائی","k":"أخرجه الحميدي في \"مسنده\": ۸۹۵، والبيهقي في \"السنن\": ۴/۱۵۸\n(الصحيحة: ۸۵۷)","e":"حدیث نبوی کے مطابق خیانت کرنا منافق کی صفت ہے، نیز اس کی سنگینی کا اندازہ اس حدیث سے لگایا جا سکتا ہے کہ اس سے بڑھ کر کون سی رسوائی ہو سکتی ہے کہ روزِ قیامت بنی آدم کے سامنے خائن نے اپنی گردن پر اونٹ یا گائے یا بکری یا تینوں قسم کے جانور اٹھا رکھے ہوں اور وہ اپنی اپنی آوازیں نکال رہے ہوں۔"}],[2194,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے دن پرہیز گار لوگ میرے دوست ہوں گے، اگر چہ وہ نسب میں قریب تر ہوں (یا نہ ہوں)۔ (خیال رکھنا) کہیں ایسا نہ ہو کہ لوگ تو میرے پاس (نیک) اعمال لے کر آئیں اور تم دنیا (کی خیانتوں اور دوسروں کے غصب شدہ حقوق) کو اپنے کندھوں پر اٹھا کر لاؤ اور پکارو: اے محمد! اور میں ادھر ادھر اعراض کرتے ہوئے کہوں: نہیں۔“ پھر آپ نے اپنی دونوں جانب اعراض کیا۔","",{"t":"خیانت کیے ہوئے اونٹ، گائے اور بکری کی وجہ سے میدانِ حشر میں رسوائی","k":"أخرجه البخاري في \"الادب المفرد\": ۸۹۷، وابن أبي عاصم في \"السنة\": ۲۱۳، ۱۰۱۲\n(الصحيحة: ۷۶۵)","e":"سبحان اللہ! اگر ہم میں رسول اللہ صلی اللہ علیہ وسلم سے محبت کرنے اور روز قیامت آپ کی صحبت اختیار کرنے کے جذبات موجود ہوں، تو اللہ تعالیٰ نے ہماری اس خواہش کو پورا کرنے کے اسباب بھی پیدا فرما دیے ہیں کہ ہر متقی اور پرہیز گار روز قیامت آپ صلی اللہ علیہ وسلم کا دوست ہو گا۔ آپ صلی اللہ علیہ وسلم کی ولایت کی بنیاد حسب و نسب پر نہیں۔ لہذا ہمیں چاہئے کہ ہم خیانتوں سے بچیں تا کہ آپ صلی اللہ علیہ وسلم ہم سے بے رخی نہ کریں اور تقوی و طہارت میں نام پیدا کر کے آپ صلی اللہ علیہ وسلم کی دوستی کے اسباب پیدا کریں۔"}],[2195,"سیدنا سہل بن ابو حثمہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر فرماتے ہوئے سنا: ”سات کبیرہ گناہوں سے اجتناب کرو۔“ لوگ خاموش رہے اور کسی نے (تفصیل کی بابت) کوئی بات نہ کی۔ آپ نے فرمایا: ”تم مجھ سے ان (سات گناہوں) کے بارے میں دریافت کیوں نہیں کرتے؟ وہ یہ ہیں: اللہ کے ساتھ کسی کو شریک ٹھہرانا، کسی جان کو ناحق قتل کرنا، کافروں سے لڑائی کے وقت راہ فرار اختیار کرنا، یتیم کا مال کھانا، سود کھانا، پاکدامن عورتوں پر تہمت لگانا اور ہجرت کے بعد پھر جنگل میں مقیم ہو کر بدو بن جانا۔“","",{"t":"سات کبیرہ گناہ","k":"أخرجه الطبراني في \"المعجم الكبير\": ۶/۱۲۴/۵۶۳۶\n(الصحيحة: ۲۲۴۴)","e":"یہ حدیث اپنے مفہوم میں واضح ہے، آخری چیز ”ہجرت کے بعد بدو بن جانا“ میں کچھ ابہام ہے۔ محمد بن سہل نے سیدنا سہل رضی اللہ عنہ سے پوچھا: ابو جان! ہجرت کے بعد بدو بننا، اس چیز کو یہاں کیوں ذکر کیا گیا؟ انھوں نے کہا: بیٹا! آدمی کا ہجرت کرنا کتنا عظیم عمل ہے، لیکن جب مال فئ میں اس کا حصہ ثابت ہوتا ہے اور جہاد فرض ہوتا ہے تو وہ اپنی گردن سے ہجرت (کے مقصد) کو اتار پھینکتا ہے اور پہلے کی طرح بدو بن جاتا ہے۔ (صحیحہ: ۲۲۴۴ کے تحت) «التعرب بعد الہجرۃ»: ابن اثیر نے (النہایۃ) میں کہا: ہجرت کرنے کے بعد پھر جنگل کی طرف لوٹ جانا اور بدوؤں کے ساتھ سکونت اختیار کرنا۔ جو آدمی ہجرت کے بعد بغیر عذر کے اپنے سابقہ مقام کی طرف چلا جاتا تھا، اسے وہ مرتد شمار کرتے تھے۔ میں (البانی) کہتا ہوں: ”التَّغَرُّبُ“ کا تعلق بھی اسی ممنوعہ صورت سے ہے، ...... بلاوجہ اسلامی ممالک سے مغربی ممالک اور دوسری کفریہ سلطنتوں کی طرف سفر کرنا۔ (صحیحہ: ۲۲۴۴) کتاب ”ایمان، توحید، دین اور تقدیر کا بیان“ میں عنوان ”غیر اسلامی ممالک میں سکونت پذیر ہونا کیسا ہے؟“ کے تحت اس موضوع پر سیر حاصل بحث ہو چکی ہے۔"}],[2196,"سیدنا سہل بن سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”صغیرہ گناہوں سے گریز کرو۔ (اور ان کو حقیر مت سمجھو، غور فرماؤ کہ) کی کچھ لوگ ایک وادی میں پڑاؤ ڈالتے ہیں، ایک آدمی ایک لکڑی لاتا ہے اور دوسرا ایک لاتا ہے۔ ...... (ایک ایک کر کے اتنی لکڑیاں جمع ہو جاتی ہیں کہ) وہ آگ جلا کر روٹیاں وغیرہ پکا لیتے ہیں۔ اسی طرح اگر صغیرہ گناہوں کی بنا پر مؤاخذہ ہو تو وہ بھی ہلاک کر سکتے ہیں۔“","",{"t":"چھوٹے گناہوں کی کثرت بھی مہلک ہے","k":"أخرجه أحمد: ۵/۳۳۱\n(الصحيحة: ۳۸۹)","e":"آپ صلی اللہ علیہ وسلم نے مثال کے ذریعے اپنا مقصود واضح کر دیا ہے کہ پوری زندگی کے معمولی معمولی گناہ جمع ہو کر انسان کی ہلاکت کا سبب بن سکتے ہیں، لہذا اللہ تعالیٰ کی ہر قسم کی نافرمانی سے اجتناب کرنا چاہیے۔ مومن و مسلمان کو چاہیے کہ وہ اللہ تعالیٰ کی معصیت سے گریز کرے، قطع نظر اس سے کہ وہ صغیرہ گناہ ہو یا کبیرہ۔"}],[2197,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ”صغیرہ گناہوں کا ارتکاب کرنے سے بچتے رہنا، کیونکہ ان کا بھی اللہ تعالیٰ کی طرف سے مؤاخذہ کیا جائے گا۔“","",{"t":"چھوٹے گناہوں کی وجہ سے مؤاخذہ","k":"أخرجه الدارمي: ۲/۳۰۳، وابن ماجه: ۴۲۴۳، وابن حبان: ۲۴۹۷، وأحمد: ۶/۷۰، ۱۵۱، وابن عساكر في \"تاريخ دمشق\": ۷/۱۷۶/۱\n(الصحيحة: ۵۱۳)","e":"مومنانہ تہذیب یہ ہے کہ کسی نیکی کو حقیر سمجھ کر ترک نہ کیا جائے اور کسی برائی کو معمولی تصور کر کے اس کا ارتکاب نہ کیا جائے، کیونکہ پوری زندگی کی معمولی معمولی غفلتیں اور سستیاں انسان کی ہلاکت کا سبب بن سکتی ہیں۔"}],[2198,"سیدنا نعمان بن بشیر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”اپنے اور حرام (امور) کے مابین کسی حلال چیز کو آڑ بنائے رکھو، جس نے ایسے کیا وہ اپنے دین اور عزت کو محفوظ کر لے گا اور جو (اس آڑ کو پھلانگ کر حرام کے) قریب تک جا پہنچے گا، وہ اس آدمی کی طرح ہے جو (ممنوعہ) چراگاہ کے ساتھ (مویشیوں کو) چرا رہا ہے (قریب ہے کہ وہ اس میں داخل ہو جائیں)۔“","",{"t":"حرام کے قریب تک نہیں پھٹکنا چاہیے","k":"أخرجه ابن حبان في \"صحيحه\": ۲۵۵۱ - موارد، والديلمي: ۱/۱/۱۳، والطبراني في \"الكبير\"\n(الصحيحة: ۸۹۶)","e":"شریعت نے حرام اور ممنوعہ امور سے بچنے کو اتنی اہمیت دی کہ ان جائز اور مباح چیزوں کے قریب جانے سے منع کر دیا، جن کے بعد حرام امور کا آغاز ہوتا ہے، اسی حدیث کے بعض طرق میں یہ الفاظ ہیں: «إِنَّ الْحَلَالَ بَيِّنٌ وَإِنَّ الْحَرَامَ بَيِّنٌ وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ فَمَنِ اتَّقَى الشُّبُهَاتِ فَقَدِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ ......» (بخاری، مسلم) ...... ”حلال بھی واضح ہے اور حرام بھی واضح ہے لیکن ان دونوں کے درمیان کچھ مشتبہ امور ہیں، اکثر لوگ ان کو نہیں جانتے، جو آدمی ان مشتبہ امور سے بھی بچا رہا، وہ اپنے دین اور عزت کو محفوظ کر لے گا اور جو ان مشتبہ چیزوں میں گھس گیا (تو یوں سمجھ لیں کہ) وہ حرام چیزوں میں گھس گیا ......“ لہذا ہمیں چاہئے کہ حرام کاموں کا ارتکاب کرنا تو درکنار، ان کے قریب تک نہ پھٹکیں، مثلا عورت کو دیکھنا حرام ہے۔ اب اس حرام کام سے بچنے کے لیے کسی اشد ضرورت کے بغیر آدمی سرے سے ان بازاروں میں نہ جایا جائے جہاں بے پردہ اور بے حیا قسم کی عورتوں کی کثرت ہو۔ اسی طرح جس مجلس میں غیبت کرنے یا سننے کا اندیشہ ہو تو سرے سے اس مجلس میں نہ بیٹھا جائے۔"}],[2199,"سیدنا فضالہ بن عبید رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”(کوئی نیکی کر کے) اپنے اور آتش دوزخ کے درمیان پردہ لٹکائے رکھو، اگر چہ وہ کھجور کے ایک ٹکڑے (کا صدقہ کرنے کی صورت میں ہو)۔“","",{"t":"صدقہ کی فضیلت","k":"رواه الطبراني في \"الكبير\"\n(الصحيحة: ۸۹۷)","e":"اللہ تعالیٰ کے مبارک نام پر صدقہ و خیرات کرنا رحمتِ خداوندی کے حصول کا سبب بنتا ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص حلال کی کمائی سے ایک کھجور کے برابر بھی صدقہ کرتا ہے اور اللہ تعالیٰ پاکیزہ کمائی کا ہی صدقہ قبول کرتا ہے تو اللہ تعالیٰ اسے اپنے دائیں ہاتھ میں لیتا ہے، پھر وہ اسے صاحبِ صدقہ کے لیے بڑھاتا رہتا ہے جیسے تم میں سے کوئی اپنے بچھیرے کو پالتا اور بڑھاتا ہے، یہاں تک کہ وہ (کھجور کے برابر کیا ہوا صدقہ) پہاڑ کی مثل ہو جاتا ہے۔“ (بخاری، مسلم) راہِ خدا میں صدقہ کرنا اتنا مبارک عمل ہے کہ کھجور کا دانہ صدقہ کیا، لیکن پہاڑ کے برابر اجر و ثواب وصول کیا۔ ہمیں چاہیے ہم اپنے اور جہنم کے مابین بڑے بڑے پہاڑ نصب کر کے اپنے آپ کو بچانے کی بھر پور کوشش کریں۔"}],[2200,"ابو راشد حبرانی کہتے ہیں کہ سیدنا ابو امامہ باہلی رضی اللہ عنہ نے میرا ہاتھ پکڑا اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا اور فرمایا: ”ابو امامہ! بعض مومن ایسے ہیں جن کا دل میرے لیے نرم (اور لچکدار) ہوتا ہے۔“","",{"t":"بعض مومنوں کے دل آپ صلی اللہ علیہ وسلم کے لیے نرم ہوتے ہیں","k":"أخرجه الأمام أحمد: ۵/۲۶۷\n(الصحيحة: ۲۴۷۰)","e":"صحابہ کرام، شمعِ نبوت کے پروانے، حدیث رسول کے جیالے، اور فرمانِ نبوی کے شیدائی تھے، سب میں آپ صلی اللہ علیہ وسلم کی اطاعت گزاری کا جذبہ موجود تھا، بہر حال بعض میں آپ کے فرمان کے سامنے سر تسلیم خم کرنے اور آپ کے حق میں نرم ہونے کا جذبہ زیادہ تھا۔"}],[2201,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب اللہ تعالیٰ اپنے بندے کے ساتھ خیر و بھلائی کا ارادہ فرماتا ہے تو اس کو (اس کے گناہوں کی سزا) جلد ہی دنیا میں دے دیتا ہے (یعنی تکلیفوں اور آزمائشوں کے ذریعے سے اس کے گناہوں کی معافی کے اسباب پیدا کر دیتا ہے) اور جب کسی بندے کے ساتھ برائی کا ارادہ کرتا ہے تو اس سے اس کے گناہوں کی سزا (دنیا میں) روک لیتا ہے، یہاں تک کہ قیامت والے دن اس کو پوری سزا دے گا۔“","",{"t":"مومن کے انجامِ خیر کے لیے دنیوی آزمائشیں بہتر ہیں","k":"رواه الترمذي: ۲/۶۴، وابن عدي: ۱۷۴/۱ و ۲، والبيهقي في \"الأسماء\" ص ۱۵۴\n(الصحيحة: ۱۲۲۰)","e":"ہر انسان طبعی طور پر غلطی کے دہانے پر کھڑا ہوتا ہے اور کسی وقت بھی اس سے کسی قسم کا گناہ سرزد ہو سکتا ہے، انبیا کے بعد کوئی کس و ناکس عفت و عصمت کا دعوی نہیں کر سکتا ہے، ہر امتی کسی نہ کسی انداز میں کوئی نہ کوئی ٹھوکر ضرور کھائے گا۔ لیکن سعادت اس میں ہے اللہ تعالیٰ روزِ محشر بشری تقاضوں کو معاف کر دے، اس خوش بختی کے لیے اللہ تعالیٰ نے رحیم و رحمان کا ثبوت دیتے ہوئے ایک قانون بنا دیا کہ دنیا میں مومن پر پڑنے والی آزمائش اور بیماریاں اس کے گناہوں کی معافی اور درجات کی بلندی کا بہت بڑا سبب ہیں۔ اس کا یہ مطلب نہیں کہ آدمی اللہ تعالیٰ سے دنیا میں مصائب کا مطالبہ کرنا شروع کر دے۔ مومن کی زندگی کا ایک ایک لمحہ اس کے لیے خیر و سعادت کا پیغام لاتا ہے، اگر اللہ تعالیٰ کی طرف سے وہ کسی آزمائش میں مبتلا ہو جائے تو صبر کا دامن ترک نہ کرے اور اگر اس کے نصیب میں صحت و تندرستی ہو تو اس نعمتِ عظمیٰ پر اللہ تعالیٰ کا اتنا شکر اور اتنی حمد و ثنا بیان کرے کہ وہ بیماریوں پر صبر کرنے کی وجہ سے ملنے والے درجات ویسے ہی عطا کر دے۔ جو انسان برا ہو، اللہ تعالیٰ کی نعمتوں سے بھر پور استفادہ بھی کر رہا ہو اور دن بدن اس کے مزاج میں بغاوت کے آثار کا ظہور ہو رہا ہو تو ایسے شخص کو بہر حال سنجیدہ فکر کرنی چاہیے، کہیں ایسا نہ ہو کہ دنیا میں اسے مہلت ملتی رہے اور آخرت میں اس کا گھیرا تنگ کر دیا جائے۔"}]])